import { SimulationNodeDatum, SimulationLinkDatum } from 'd3';

export interface GraphNode extends SimulationNodeDatum {
  id: string;
  label: string;
  group: number;
  description?: string;
  isExpanded?: boolean;
}

export interface GraphLink extends SimulationLinkDatum<GraphNode> {
  source: string | GraphNode;
  target: string | GraphNode;
}

export interface GraphData {
  nodes: GraphNode[];
  links: GraphLink[];
}

export interface GeminiGraphResponse {
  nodes: Array<{ id: string; label: string; group: number; description: string }>;
  links: Array<{ source: string; target: string }>;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GeminiGraphResponse } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const graphSchema = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING, description: "A unique short ID for the node" },
          label: { type: Type.STRING, description: "Display name of the concept" },
          group: { type: Type.INTEGER, description: "A category group number (1-5)" },
          description: { type: Type.STRING, description: "A one-sentence summary" }
        },
        required: ["id", "label", "group", "description"]
      }
    },
    links: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "The ID of the source node" },
          target: { type: Type.STRING, description: "The ID of the target node" }
        },
        required: ["source", "target"]
      }
    }
  },
  required: ["nodes", "links"]
};

export const generateInitialGraph = async (topic: string): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Generate a knowledge graph for the topic: "${topic}". Provide about 8-12 foundational nodes and their logical relationships.`,
    config: {
      systemInstruction: "You are an expert knowledge engineer. Create structured concept maps in JSON format. Ensure all link source/target IDs exist in the nodes list.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });

  return JSON.parse(response.text);
};

export const expandNode = async (nodeLabel: string, contextTopic: string, existingNodes: string[]): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `The user clicked on "${nodeLabel}" within the context of "${contextTopic}". Generate 5-7 more specific sub-topics or closely related concepts that branch off from "${nodeLabel}". Avoid these existing node labels: ${existingNodes.join(', ')}.`,
    config: {
      systemInstruction: "Expand the knowledge graph. The new nodes should primarily link to the clicked node, but can also link to each other.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });

  return JSON.parse(response.text);
};

import React, { useEffect, useRef, useMemo } from 'react';
import * as d3 from 'd3';
import { GraphNode, GraphLink, GraphData } from '../types';

interface GraphProps {
  data: GraphData;
  onNodeClick: (node: GraphNode) => void;
  isLoading: boolean;
}

const Graph: React.FC<GraphProps> = ({ data, onNodeClick, isLoading }) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const simulationRef = useRef<d3.Simulation<GraphNode, GraphLink> | null>(null);

  const colors = [
    '#38bdf8', // sky-400
    '#4ade80', // green-400
    '#f87171', // red-400
    '#fbbf24', // amber-400
    '#a78bfa', // violet-400
    '#f472b6', // pink-400
  ];

  useEffect(() => {
    if (!svgRef.current) return;

    const svg = d3.select(svgRef.current);
    const width = window.innerWidth;
    const height = window.innerHeight;

    svg.selectAll('*').remove();

    const container = svg.append('g');

    // Zoom behavior
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 4])
      .on('zoom', (event) => {
        container.attr('transform', event.transform);
      });

    svg.call(zoom);

    // Simulation setup
    const simulation = d3.forceSimulation<GraphNode>(data.nodes)
      .force('link', d3.forceLink<GraphNode, GraphLink>(data.links)
        .id(d => d.id)
        .distance(120)
        .strength(0.5)
      )
      .force('charge', d3.forceManyBody().strength(-400))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(50));

    simulationRef.current = simulation;

    // Links
    const link = container.append('g')
      .attr('class', 'links')
      .selectAll('line')
      .data(data.links)
      .enter().append('line')
      .attr('stroke', '#334155')
      .attr('stroke-opacity', 0.6)
      .attr('stroke-width', 2);

    // Nodes
    const node = container.append('g')
      .attr('class', 'nodes')
      .selectAll('g')
      .data(data.nodes)
      .enter().append('g')
      .attr('class', 'node-group')
      .style('cursor', 'pointer')
      .on('click', (event, d) => {
        event.stopPropagation();
        triggerExplosion(d);
        onNodeClick(d);
      })
      .call(d3.drag<SVGGElement, GraphNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        })
      );

    node.append('circle')
      .attr('r', 18)
      .attr('fill', d => colors[d.group % colors.length] || colors[0])
      .attr('stroke', '#0f172a')
      .attr('stroke-width', 3)
      .attr('class', 'transition-all duration-300 hover:scale-125');

    node.append('text')
      .attr('dx', 24)
      .attr('dy', '.35em')
      .text(d => d.label)
      .attr('fill', '#f1f5f9')
      .attr('font-size', '14px')
      .attr('font-weight', '500')
      .style('pointer-events', 'none')
      .style('text-shadow', '0 2px 4px rgba(0,0,0,0.8)');

    simulation.on('tick', () => {
      link
        .attr('x1', d => (d.source as GraphNode).x!)
        .attr('y1', d => (d.source as GraphNode).y!)
        .attr('x2', d => (d.target as GraphNode).x!)
        .attr('y2', d => (d.target as GraphNode).y!);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    function triggerExplosion(anchor: GraphNode) {
      const strength = 15;
      const radius = 250;

      data.nodes.forEach(n => {
        if (n.id === anchor.id) return;
        const dx = (n.x || 0) - (anchor.x || 0);
        const dy = (n.y || 0) - (anchor.y || 0);
        const distance = Math.sqrt(dx * dx + dy * dy) || 1;

        if (distance < radius) {
          const force = (radius - distance) / radius;
          n.vx = (n.vx || 0) + (dx / distance) * force * strength;
          n.vy = (n.vy || 0) + (dy / distance) * force * strength;
        }
      });

      simulation.alpha(0.8).restart();
    }

    return () => {
      simulation.stop();
    };
  }, [data, onNodeClick]);

  return (
    <div className="relative w-full h-full bg-slate-950 overflow-hidden">
      <svg
        ref={svgRef}
        className="w-full h-full"
        style={{ touchAction: 'none' }}
      />
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-sm pointer-events-none transition-opacity duration-300">
          <div className="flex flex-col items-center gap-4">
            <div className="w-12 h-12 border-4 border-sky-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-sky-400 font-medium animate-pulse">Consulting the Knowledge Base...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Graph;

import React, { useState, useCallback, useRef } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse } from './types';
import * as gemini from './services/geminiService';
import Graph from './components/Graph';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [currentTopic, setCurrentTopic] = useState('');
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);

  // Use a ref to keep track of existing node IDs to prevent duplicates and ensure coordinates persist
  const nodeCache = useRef<Map<string, GraphNode>>(new Map());

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;

    setLoading(true);
    try {
      const response = await gemini.generateInitialGraph(topic);
      processNewData(response);
      setCurrentTopic(topic);
    } catch (error) {
      console.error("Search failed:", error);
      alert("Failed to generate graph. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const processNewData = (newData: GeminiGraphResponse) => {
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];

      newData.nodes.forEach(node => {
        if (!nodeCache.current.has(node.id)) {
          const newNode: GraphNode = { ...node };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
        }
      });

      newData.links.forEach(link => {
        const linkId = `${link.source}-${link.target}`;
        const reverseLinkId = `${link.target}-${link.source}`;

        // Very basic deduplication of links
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });

        if (!exists) {
          updatedLinks.push(link);
        }
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    if (node.isExpanded) return;

    setLoading(true);
    try {
      const existingLabels = Array.from(nodeCache.current.values()).map(n => n.label);
      const response = await gemini.expandNode(node.label, currentTopic, existingLabels);

      // Mark original node as expanded
      node.isExpanded = true;

      processNewData(response);
    } catch (error) {
      console.error("Expansion failed:", error);
    } finally {
      setLoading(false);
    }
  }, [currentTopic]);

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 font-sans selection:bg-sky-500/30">
      {/* Header / Search */}
      <header className="z-10 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 p-4 flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-sky-400 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-sky-500/20">
            <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">Knowledge Exploder</h1>
            <p className="text-xs text-slate-400 uppercase tracking-widest">AI-Powered Mind Mapping</p>
          </div>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-xl w-full flex items-center gap-2">
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Enter a concept (e.g., Quantum Computing, Roman Empire)..."
            className="flex-1 bg-slate-800 border border-slate-700 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-sky-500/50 transition-all placeholder:text-slate-500"
          />
          <button
            type="submit"
            disabled={loading}
            className="bg-sky-500 hover:bg-sky-400 disabled:bg-slate-700 text-white font-semibold px-6 py-2 rounded-lg shadow-lg shadow-sky-500/20 transition-all active:scale-95"
          >
            Explode
          </button>
        </form>

        <div className="hidden lg:flex items-center gap-4 text-sm text-slate-400">
          <div className="flex items-center gap-1">
            <kbd className="bg-slate-800 px-1.5 py-0.5 rounded border border-slate-700 text-[10px]">CLICK</kbd>
            <span>to expand</span>
          </div>
          <div className="flex items-center gap-1">
            <kbd className="bg-slate-800 px-1.5 py-0.5 rounded border border-slate-700 text-[10px]">SCROLL</kbd>
            <span>to zoom</span>
          </div>
        </div>
      </header>

      {/* Main View */}
      <main className="flex-1 relative">
        {graphData.nodes.length > 0 ? (
          <Graph data={graphData} onNodeClick={handleNodeClick} isLoading={loading} />
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 to-slate-950">
            <div className="max-w-lg space-y-6">
              <div className="w-24 h-24 bg-slate-800 rounded-3xl mx-auto flex items-center justify-center animate-pulse">
                <svg className="w-12 h-12 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.628.283a2 2 0 01-1.186.128l-2.315-.463a2 2 0 00-1.022.547l-2.387.477a6 6 0 00-3.86.517l-.628.283a2 2 0 01-1.186.128L4 16.5m0 0l-1.5-1.5M4 16.5l1.5 1.5M19.428 15.428L21 17l-1.5 1.5M19.428 15.428l-1.5-1.5" />
                </svg>
              </div>
              <h2 className="text-3xl font-bold text-slate-200">Start Your Exploration</h2>
              <p className="text-slate-400 leading-relaxed">
                Type a topic above to generate a dynamic concept map. 
                Clicking on a node will use AI to "explode" it into deeper sub-topics, 
                letting you navigate the universe of knowledge.
              </p>
            </div>
          </div>
