            </div>
            <p className="text-sm text-slate-300 leading-relaxed mb-4">
              {selectedNode.description || "A key concept in this knowledge domain."}
            </p>
            <div className="flex items-center gap-2">
               <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Group {selectedNode.group}</span>
               <div className="h-1 flex-1 bg-slate-800 rounded-full overflow-hidden">
                 <div 
                   className="h-full bg-sky-500" 
                   style={{ width: `${(selectedNode.group / 5) * 100}%` }}
                 />
               </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="p-3 bg-slate-900 border-t border-slate-800 text-[10px] text-slate-600 flex justify-between items-center px-6">
        <p>&copy; 2024 Knowledge Exploder &bull; Powered by Gemini 3 Flash</p>
        <div className="flex items-center gap-4">
          <span className="flex items-center gap-1">
            <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>
            System Active
          </span>
        </div>
      </footer>
    </div>
  );
};

export default App;

