                <svg className="w-12 h-12 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
              </div>
              <h2 className="text-3xl font-bold text-slate-200">Start Your Exploration</h2>
              <p className="text-slate-400 leading-relaxed">
                Type a topic above to generate a dynamic concept map. 
                Clicking on a node will use AI to "explode" it into deeper sub-topics.
              </p>
            </div>
          </div>
        )}

        {/* Node Detail Info Panel */}
        {selectedNode && (
          <div className="absolute bottom-6 left-6 w-80 bg-slate-900/95 backdrop-blur-xl border border-slate-700/50 rounded-2xl p-5 shadow-2xl animate-in slide-in-from-bottom-4 duration-300 z-20">
            <div className="flex justify-between items-start mb-3">
