import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { GraphNode, GraphLink, GraphData } from '../types';

interface GraphProps {
  data: GraphData;
  onNodeClick: (node: GraphNode) => void;
  isLoading: boolean;
}

const Graph: React.FC<GraphProps> = ({ data, onNodeClick, isLoading }) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<SVGGElement>(null);
  const simulationRef = useRef<d3.Simulation<GraphNode, GraphLink> | null>(null);

  const colors = [
    '#38bdf8', // sky-400
    '#4ade80', // green-400
    '#f87171', // red-400
    '#fbbf24', // amber-400
    '#a78bfa', // violet-400
    '#f472b6', // pink-400
  ];

  // Initialize simulation once
  useEffect(() => {
    if (!svgRef.current) return;

    const svg = d3.select(svgRef.current);
    const width = window.innerWidth;
    const height = window.innerHeight;

    const simulation = d3.forceSimulation<GraphNode>()
      .force('link', d3.forceLink<GraphNode, GraphLink>().id(d => d.id).distance(100).strength(1))
      .force('charge', d3.forceManyBody().strength(-300))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(40));

    simulationRef.current = simulation;

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 4])
      .on('zoom', (event) => {
        d3.select(containerRef.current).attr('transform', event.transform);
      });

    svg.call(zoom);

    return () => {
      simulation.stop();
    };
  }, []);

  // Update simulation when data changes
  useEffect(() => {
    if (!simulationRef.current || !containerRef.current) return;

    const simulation = simulationRef.current;
    const container = d3.select(containerRef.current);

    // Sync simulation with latest nodes/links
    simulation.nodes(data.nodes);
    const linkForce = simulation.force<d3.ForceLink<GraphNode, GraphLink>>('link');
    if (linkForce) linkForce.links(data.links);

    // Link Join
    let link = container.selectAll<SVGLineElement, GraphLink>('.link')
      .data(data.links, d => `${(d.source as any).id || d.source}-${(d.target as any).id || d.target}`);

    link.exit().remove();
    const linkEnter = link.enter()
      .append('line')
      .attr('class', 'link')
      .attr('stroke', '#334155')
      .attr('stroke-opacity', 0.6)
      .attr('stroke-width', 2);

    link = linkEnter.merge(link);

    // Node Join
    let node = container.selectAll<SVGGElement, GraphNode>('.node-group')
      .data(data.nodes, d => d.id);

    node.exit().remove();

    const nodeEnter = node.enter()
      .append('g')
      .attr('class', 'node-group')
      .style('cursor', 'pointer')
      .on('click', (event, d) => {
        event.stopPropagation();
        triggerExplosion(d);
        onNodeClick(d);
      })
      .call(d3.drag<SVGGElement, GraphNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x;
          d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x;
          d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null;
          d.fy = null;
        })
      );

    nodeEnter.append('circle')
      .attr('r', 18)
      .attr('fill', d => colors[d.group % colors.length] || colors[0])
      .attr('stroke', '#0f172a')
      .attr('stroke-width', 3);

    nodeEnter.append('text')
      .attr('dx', 24)
      .attr('dy', '.35em')
      .attr('fill', '#f1f5f9')
      .attr('font-size', '14px')
      .attr('font-weight', '500')
      .style('pointer-events', 'none')
      .style('text-shadow', '0 2px 4px rgba(0,0,0,0.8)');

    node = nodeEnter.merge(node);
    node.select('text').text(d => d.label);

    simulation.on('tick', () => {
      link
        .attr('x1', d => (d.source as any).x)
        .attr('y1', d => (d.source as any).y)
        .attr('x2', d => (d.target as any).x)
        .attr('y2', d => (d.target as any).y);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    function triggerExplosion(anchor: GraphNode) {
      const strength = 15;
      const radius = 250;
      data.nodes.forEach(n => {
        if (n.id === anchor.id) return;
        const dx = (n.x || 0) - (anchor.x || 0);
        const dy = (n.y || 0) - (anchor.y || 0);
        const distance = Math.sqrt(dx * dx + dy * dy) || 1;
        if (distance < radius) {
          const force = (radius - distance) / radius;
          n.vx = (n.vx || 0) + (dx / distance) * force * strength;
          n.vy = (n.vy || 0) + (dy / distance) * force * strength;
        }
      });
      simulation.alpha(0.8).restart();
    }

    // Warm up simulation for new items
    simulation.alpha(0.5).restart();

  }, [data, onNodeClick]);

  return (
    <div className="relative w-full h-full bg-slate-950 overflow-hidden">
      <svg ref={svgRef} className="w-full h-full" style={{ touchAction: 'none' }}>
        <g ref={containerRef} />
      </svg>
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/10 backdrop-blur-[2px] pointer-events-none transition-opacity duration-300">
          <div className="flex flex-col items-center gap-4 bg-slate-900/80 p-6 rounded-2xl border border-slate-700 shadow-2xl">
            <div className="w-10 h-10 border-4 border-sky-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-sky-400 font-medium animate-pulse">Expanding Knowledge...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Graph;

import React, { useState, useCallback, useRef } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse } from './types';
import * as gemini from './services/geminiService';
import Graph from './components/Graph';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [currentTopic, setCurrentTopic] = useState('');
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);

  const [briefing, setBriefing] = useState<string | null>(null);
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;

    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    try {
      const response = await gemini.generateInitialGraph(topic);
      processNewData(response);
      setCurrentTopic(topic);
    } catch (error) {
      console.error("Search failed:", error);
      alert("Failed to generate graph. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  /**
   * Processes new node/link data from Gemini, ensuring stability.
   * @param newData The new data batch
   * @param parentNode Optional anchor node where new sub-nodes should appear
   */
  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode) => {
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];

      // 1. Add new nodes, initializing coordinates from parent to prevent fly-off
      newData.nodes.forEach(node => {
        if (!nodeCache.current.has(node.id)) {
          const newNode: GraphNode = { 
            ...node,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 20 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 20 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
        }
      });

      // 2. Add new links, only if both nodes exist (link integrity)
      newData.links.forEach(link => {
        if (!nodeCache.current.has(link.source) || !nodeCache.current.has(link.target)) {
          return; // Skip broken links
        }

        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : (l.source as GraphNode).id;
          const t = typeof l.target === 'string' ? l.target : (l.target as GraphNode).id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });

        if (!exists) {
          updatedLinks.push(link as GraphLink);
        }
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    if (node.isExpanded) return;

    setLoading(true);
    try {
      const existingLabels = [...nodeCache.current.values()].map(n => n.label);
      const response = await gemini.expandNode(node.label, currentTopic, existingLabels);
      node.isExpanded = true;
      processNewData(response, node);
    } catch (error) {
      console.error("Expansion failed:", error);
    } finally {
      setLoading(false);
    }
  }, [currentTopic]);

  const handleExportData = () => {
    const dataStr = JSON.stringify({ ...graphData, topic: currentTopic }, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `knowledge-graph-${(currentTopic || 'export').toLowerCase().replace(/\s+/g, '-')}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data && Array.isArray(data.nodes) && Array.isArray(data.links)) {
          nodeCache.current.clear();
          setSelectedNode(null);

          const cleanNodes = data.nodes.map((n: any) => {
            const { x, y, vx, vy, fx, fy, ...rest } = n;
            const node = rest as GraphNode;
            nodeCache.current.set(node.id, node);
            return node;
          });

          setGraphData({ nodes: cleanNodes, links: data.links });
          if (data.topic) {
            setCurrentTopic(data.topic);
            setTopic(data.topic);
          }
        } else {
          alert("Invalid knowledge graph data format.");
        }
      } catch (err) {
        console.error("Upload failed:", err);
        alert("Failed to parse the JSON file.");
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const handleGenerateBriefing = async () => {
    if (graphData.nodes.length === 0) return;
    setIsBriefingLoading(true);
    setBriefing("");
    try {
      const result = await gemini.generateBriefing(currentTopic || "Current Session", graphData.nodes);
      setBriefing(result);
    } catch (error) {
      console.error("Briefing failed:", error);
      alert("Could not generate briefing.");
    } finally {
      setIsBriefingLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 font-sans selection:bg-sky-500/30">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        accept=".json" 
        className="hidden" 
      />

      <header className="z-10 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 p-4 flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-sky-400 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-sky-500/20">
            <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-bold tracking-tight">Knowledge Exploder</h1>
            <p className="text-xs text-slate-400 uppercase tracking-widest">AI-Powered Mind Mapping</p>
          </div>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-xl w-full flex items-center gap-2">
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Search topic..."
            className="flex-1 bg-slate-800 border border-slate-700 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-sky-500/50 transition-all placeholder:text-slate-500"
          />
          <button
            type="submit"
            disabled={loading}
            className="bg-sky-500 hover:bg-sky-400 disabled:bg-slate-700 text-white font-semibold px-4 py-2 rounded-lg transition-all active:scale-95"
          >
            Explode
          </button>
        </form>

        <div className="flex items-center gap-2">
          <button
            onClick={handleGenerateBriefing}
            disabled={graphData.nodes.length === 0 || loading || isBriefingLoading}
            className="p-2 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-sky-400 rounded-lg border border-slate-700 transition-colors"
            title="Generate Briefing"
