import { SimulationNodeDatum, SimulationLinkDatum } from 'd3';

export interface GraphNode extends SimulationNodeDatum {
  id: string;
  label: string;
  group: number;
  description?: string;
  isExpanded?: boolean;
  wikiUrl?: string;
  wikiSummary?: string;
  wikiImage?: string;
  x?: number;
  y?: number;
  vx?: number;
  vy?: number;
  fx?: number | null;
  fy?: number | null;
}

export interface GraphLink extends SimulationLinkDatum<GraphNode> {
  source: string | GraphNode;
  target: string | GraphNode;
  relationship?: string;
}

export interface GraphData {
  nodes: GraphNode[];
  links: GraphLink[];
}

export interface GeminiGraphResponse {
  nodes: Array<{ id: string; label: string; group: number; description: string }>;
  links: Array<{ source: string; target: string; relationship: string }>;
}

export interface WikiData {
  summary: string;
  url: string;
  image?: string;
}

export const fetchWikiSummary = async (query: string): Promise<WikiData | null> => {
  try {
    // Wikipedia search to get the most relevant page
    const searchRes = await fetch(`https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(query)}&format=json&origin=*`);
    const searchData = await searchRes.json();

    if (!searchData.query.search.length) return null;

    const title = searchData.query.search[0].title;

    // Get summary and image
    const summaryRes = await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(title)}`);
    const summaryData = await summaryRes.json();

    return {
      summary: summaryData.extract,
      url: summaryData.content_urls.desktop.page,
      image: summaryData.thumbnail?.original || summaryData.thumbnail?.source
    };
  } catch (error) {
    console.error("Wiki fetch failed:", error);
    return null;
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { GeminiGraphResponse, GraphNode } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const graphSchema = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING, description: "A unique short ID" },
          label: { type: Type.STRING, description: "Display name" },
          group: { type: Type.INTEGER, description: "Category group (1-5)" },
          description: { type: Type.STRING, description: "One-sentence summary" }
        },
        required: ["id", "label", "group", "description"]
      }
    },
    links: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Source node ID" },
          target: { type: Type.STRING, description: "Target node ID" },
          relationship: { type: Type.STRING, description: "Short label describing the connection (e.g., 'Causes', 'Used by', 'Part of')" }
        },
        required: ["source", "target", "relationship"]
      }
    }
  },
  required: ["nodes", "links"]
};

export const generateInitialGraph = async (topic: string): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Generate a high-intelligence knowledge graph for: "${topic}". Focus on foundational pillars and how they interrelate.`,
    config: {
      systemInstruction: "You are a master ontologist. Map concepts with precise logical relationships.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const expandNode = async (nodeLabel: string, contextTopic: string, existingNodes: string[]): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Expand on "${nodeLabel}" within the context of "${contextTopic}". Generate deep sub-concepts. Avoid repeats: ${existingNodes.join(', ')}.`,
    config: {
      systemInstruction: "Deeper drill-down into specific sub-topics. Create complex, intelligent edges.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const generateBriefing = async (topic: string, nodes: GraphNode[]): Promise<string> => {
  const concepts = nodes.map(n => `- **${n.label}**: ${n.description}`).join('\n');
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Summarize this knowledge exploration of "${topic}".\n${concepts}`,
    config: {
      systemInstruction: "Provide a high-level strategic summary of the explored concept map.",
    }
  });
  return response.text || "Briefing unavailable.";
};

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { GraphNode, GraphLink, GraphData } from '../types';

interface GraphProps {
  data: GraphData;
  onNodeClick: (node: GraphNode) => void;
  isLoading: boolean;
}

const Graph: React.FC<GraphProps> = ({ data, onNodeClick, isLoading }) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<SVGGElement>(null);
  const simulationRef = useRef<d3.Simulation<GraphNode, GraphLink> | null>(null);

  const colors = ['#38bdf8', '#4ade80', '#f87171', '#fbbf24', '#a78bfa', '#f472b6'];

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    const width = window.innerWidth;
    const height = window.innerHeight;

    const simulation = d3.forceSimulation<GraphNode>()
      .force('link', d3.forceLink<GraphNode, GraphLink>().id(d => d.id).distance(150).strength(0.7))
      .force('charge', d3.forceManyBody().strength(-500))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(60));

    simulationRef.current = simulation;

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 4])
      .on('zoom', (event) => {
        d3.select(containerRef.current).attr('transform', event.transform);
        const k = event.transform.k;
        // Fade labels based on zoom
        d3.selectAll('.edge-label').style('opacity', k > 0.8 ? 0.7 : 0);
      });

    svg.call(zoom);

    return () => { simulation.stop(); };
  }, []);

  useEffect(() => {
    if (!simulationRef.current || !containerRef.current) return;
    const simulation = simulationRef.current;
    const container = d3.select(containerRef.current);

    simulation.nodes(data.nodes);
    const linkForce = simulation.force<d3.ForceLink<GraphNode, GraphLink>>('link');
    if (linkForce) linkForce.links(data.links);

    // Links
    let linkGroup = container.selectAll<SVGGElement, GraphLink>('.link-group')
      .data(data.links, d => `${(d.source as any).id || d.source}-${(d.target as any).id || d.target}`);

    linkGroup.exit().remove();
    const linkEnter = linkGroup.enter().append('g').attr('class', 'link-group');

    linkEnter.append('line')
      .attr('class', 'link')
      .attr('stroke', '#1e293b')
      .attr('stroke-width', 2);

    linkEnter.append('text')
      .attr('class', 'edge-label')
      .attr('text-anchor', 'middle')
      .attr('fill', '#94a3b8')
      .attr('font-size', '10px')
      .attr('dy', -5)
      .text(d => d.relationship || '');

    linkGroup = linkEnter.merge(linkGroup);

    // Nodes
    let node = container.selectAll<SVGGElement, GraphNode>('.node-group')
      .data(data.nodes, d => d.id);

    node.exit().remove();
    const nodeEnter = node.enter()
      .append('g')
      .attr('class', 'node-group')
      .on('click', (event, d) => {
        event.stopPropagation();
        onNodeClick(d);
      })
      .call(d3.drag<SVGGElement, GraphNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x; d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x; d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null; d.fy = null;
        })
      );

    nodeEnter.append('circle')
      .attr('r', 22)
      .attr('fill', d => colors[d.group % colors.length])
      .attr('stroke', '#020617')
      .attr('stroke-width', 3)
      .attr('class', 'transition-transform duration-300 hover:scale-110 shadow-lg shadow-black/50');

    nodeEnter.append('text')
      .attr('dx', 28)
      .attr('dy', '.35em')
      .attr('fill', '#f8fafc')
      .attr('font-size', '14px')
      .attr('font-weight', '600')
      .style('pointer-events', 'none')
      .style('text-shadow', '0 2px 4px rgba(0,0,0,1)');

    node = nodeEnter.merge(node);
    node.select('text').text(d => d.label);

    simulation.on('tick', () => {
      linkGroup.select('line')
        .attr('x1', d => (d.source as any).x)
        .attr('y1', d => (d.source as any).y)
        .attr('x2', d => (d.target as any).x)
        .attr('y2', d => (d.target as any).y);

      linkGroup.select('text')
        .attr('x', d => ((d.source as any).x + (d.target as any).x) / 2)
        .attr('y', d => ((d.source as any).y + (d.target as any).y) / 2);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    simulation.alpha(0.5).restart();
  }, [data, onNodeClick]);

  return (
    <div className="relative w-full h-full bg-slate-950">
      <svg ref={svgRef} className="w-full h-full" style={{ touchAction: 'none' }}>
        <g ref={containerRef} />
      </svg>
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px] pointer-events-none">
          <div className="flex flex-col items-center gap-4 bg-slate-900/90 p-8 rounded-3xl border border-sky-500/30 shadow-2xl">
            <div className="w-12 h-12 border-4 border-sky-400 border-t-transparent rounded-full animate-spin shadow-[0_0_15px_rgba(56,189,248,0.5)]"></div>
            <p className="text-sky-400 font-bold tracking-widest uppercase text-xs animate-pulse">Processing Synthesis...</p>
          </div>
        </div>
      )}
    </div>
  );
};

