import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [currentTopic, setCurrentTopic] = useState('');
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);

  const [briefing, setBriefing] = useState<string | null>(null);
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    try {
      const response = await gemini.generateInitialGraph(topic);
      processNewData(response);
      setCurrentTopic(topic);
    } catch (error) {
      alert("Synthesis failed.");
    } finally {
      setLoading(false);
    }
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode) => {
    let newNodesAdded: GraphNode[] = [];
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];

      newData.nodes.forEach(node => {
        if (!nodeCache.current.has(node.id)) {
          const newNode: GraphNode = { 
            ...node,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 50 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 50 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
          newNodesAdded.push(newNode);
        }
      });

      newData.links.forEach(link => {
        if (!nodeCache.current.has(link.source) || !nodeCache.current.has(link.target)) return;
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists) updatedLinks.push(link as GraphLink);
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });

    // Neural Pilot logic: auto-explode a random new node if enabled
    if (autoExplode && newNodesAdded.length > 0 && !loading) {
      setTimeout(() => {
        const next = newNodesAdded[Math.floor(Math.random() * newNodesAdded.length)];
        handleNodeClick(next);
      }, 3000);
    }
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);

    // Fetch Wikipedia data in background
    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    if (node.isExpanded) return;
    setLoading(true);
    try {
      const existingLabels = [...nodeCache.current.values()].map(n => n.label);
      const response = await gemini.expandNode(node.label, currentTopic, existingLabels);
      node.isExpanded = true;
      processNewData(response, node);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, [currentTopic, autoExplode]);

  const handleExportData = () => {
    const dataStr = JSON.stringify({ ...graphData, topic: currentTopic }, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `graph-${currentTopic.replace(/\s/g, '-')}.json`;
    link.click();
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 font-sans overflow-hidden">
      <header className="z-10 bg-slate-900/60 backdrop-blur-xl border-b border-slate-800 p-4 flex flex-col md:flex-row items-center gap-4">
        <div className="flex items-center gap-3 pr-4 border-r border-slate-800">
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg transition-all duration-500 ${autoExplode ? 'bg-sky-500 shadow-sky-500/40 scale-110' : 'bg-slate-800 shadow-black'}`}>
            <svg className={`w-6 h-6 ${autoExplode ? 'animate-pulse text-white' : 'text-slate-500'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div className="hidden lg:block">
            <h1 className="text-lg font-black italic tracking-tighter">NEURALPILOT</h1>
            <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Knowledge Autonomy</p>
          </div>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-xl w-full flex items-center gap-2">
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Seed the exploration..."
            className="flex-1 bg-slate-800/50 border border-slate-700/50 rounded-xl px-4 py-2.5 focus:outline-none focus:ring-2 focus:ring-sky-500/30 transition-all placeholder:text-slate-600 text-sm"
          />
          <button type="submit" disabled={loading} className="bg-sky-600 hover:bg-sky-500 disabled:opacity-30 text-white font-bold px-6 py-2.5 rounded-xl text-sm transition-all active:scale-95">
            INITIATE
          </button>
        </form>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-800/40 border border-slate-700/50 rounded-full cursor-pointer hover:bg-slate-700/50 transition-colors" onClick={() => setAutoExplode(!autoExplode)}>
            <div className={`w-3 h-3 rounded-full ${autoExplode ? 'bg-sky-400 shadow-[0_0_8px_rgba(56,189,248,0.8)]' : 'bg-slate-600'}`}></div>
            <span className="text-[10px] font-bold uppercase tracking-wider">{autoExplode ? 'Neural Pilot On' : 'Neural Pilot Off'}</span>
          </div>

          <div className="h-6 w-px bg-slate-800"></div>

