import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const STORAGE_KEY = 'knowledge_exploder_state';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [currentTopic, setCurrentTopic] = useState('');
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);

  const [briefing, setBriefing] = useState<string | null>(null);
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 1. Initial Load from LocalStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.graphData && Array.isArray(parsed.graphData.nodes)) {
          // Rebuild node cache
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => nodeCache.current.set(n.id, n));

          setGraphData(parsed.graphData);
          setCurrentTopic(parsed.currentTopic || '');
          setTopic(parsed.currentTopic || '');
          setAutoExplode(!!parsed.autoExplode);
        }
      } catch (e) {
        console.error("Failed to load saved state:", e);
      }
    }
  }, []);

  // 2. Save to LocalStorage whenever graphData, topic, or autoExplode changes
  useEffect(() => {
    if (graphData.nodes.length === 0) return;

    // To avoid circular structures caused by D3 (links referencing node objects),
    // we convert links back to ID-based references for storage.
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));

    const stateToSave = {
      graphData: {
        nodes: graphData.nodes,
        links: serializableLinks
      },
      currentTopic,
      autoExplode
    };

    localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
  }, [graphData, currentTopic, autoExplode]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    localStorage.removeItem(STORAGE_KEY); // Reset storage on new explicit search
    try {
      const response = await gemini.generateInitialGraph(topic);
      processNewData(response);
      setCurrentTopic(topic);
    } catch (error) {
      alert("Synthesis failed.");
    } finally {
      setLoading(false);
    }
  };

  const clearSession = () => {
    if (window.confirm("Are you sure you want to clear the current knowledge graph?")) {
      setGraphData({ nodes: [], links: [] });
      setTopic('');
      setCurrentTopic('');
      nodeCache.current.clear();
      setSelectedNode(null);
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode) => {
    let newNodesAdded: GraphNode[] = [];
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];

      newData.nodes.forEach(node => {
        if (!nodeCache.current.has(node.id)) {
          const newNode: GraphNode = { 
            ...node,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 50 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 50 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
          newNodesAdded.push(newNode);
        }
      });

      newData.links.forEach(link => {
        if (!nodeCache.current.has(link.source) || !nodeCache.current.has(link.target)) return;
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists) updatedLinks.push(link as GraphLink);
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });

    if (autoExplode && newNodesAdded.length > 0 && !loading) {
      setTimeout(() => {
        const next = newNodesAdded[Math.floor(Math.random() * newNodesAdded.length)];
        handleNodeClick(next);
      }, 3000);
    }
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);

    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    if (node.isExpanded) return;
    setLoading(true);
    try {
      const existingLabels = [...nodeCache.current.values()].map(n => n.label);
      const response = await gemini.expandNode(node.label, currentTopic, existingLabels);
      node.isExpanded = true;
      processNewData(response, node);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, [currentTopic, autoExplode]);

  const handleExportData = () => {
    const dataStr = JSON.stringify({ ...graphData, topic: currentTopic }, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `graph-${currentTopic.replace(/\s/g, '-')}.json`;
    link.click();
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);
        if (data && Array.isArray(data.nodes)) {
          nodeCache.current.clear();
          data.nodes.forEach((n: GraphNode) => nodeCache.current.set(n.id, n));
          setGraphData(data);
          setCurrentTopic(data.topic || '');
          setTopic(data.topic || '');
        }
      } catch (err) {
        alert("Parse failed.");
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  return (
    <div className="flex flex-col h-screen bg-slate-950 text-slate-100 font-sans overflow-hidden">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        accept=".json" 
        className="hidden" 
      />

      <header className="z-10 bg-slate-900/60 backdrop-blur-xl border-b border-slate-800 p-4 flex flex-col md:flex-row items-center gap-4">
        <div className="flex items-center gap-3 pr-4 border-r border-slate-800">
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg transition-all duration-500 ${autoExplode ? 'bg-sky-500 shadow-sky-500/40 scale-110' : 'bg-slate-800 shadow-black'}`}>
            <svg className={`w-6 h-6 ${autoExplode ? 'animate-pulse text-white' : 'text-slate-500'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div className="hidden lg:block">
            <h1 className="text-lg font-black italic tracking-tighter">NEURALPILOT</h1>
            <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Knowledge Autonomy</p>
          </div>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-xl w-full flex items-center gap-2">
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Seed the exploration..."
            className="flex-1 bg-slate-800/50 border border-slate-700/50 rounded-xl px-4 py-2.5 focus:outline-none focus:ring-2 focus:ring-sky-500/30 transition-all placeholder:text-slate-600 text-sm"
          />
          <button type="submit" disabled={loading} className="bg-sky-600 hover:bg-sky-500 disabled:opacity-30 text-white font-bold px-6 py-2.5 rounded-xl text-sm transition-all active:scale-95">
            INITIATE
          </button>
        </form>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-800/40 border border-slate-700/50 rounded-full cursor-pointer hover:bg-slate-700/50 transition-colors" onClick={() => setAutoExplode(!autoExplode)}>
            <div className={`w-3 h-3 rounded-full ${autoExplode ? 'bg-sky-400 shadow-[0_0_8px_rgba(56,189,248,0.8)]' : 'bg-slate-600'}`}></div>
            <span className="text-[10px] font-bold uppercase tracking-wider">{autoExplode ? 'Neural Pilot On' : 'Neural Pilot Off'}</span>
          </div>

          <div className="h-6 w-px bg-slate-800"></div>

          <button onClick={clearSession} disabled={!currentTopic} className="p-2 text-slate-400 hover:text-red-400 transition-colors" title="Clear Session"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg></button>
          <button onClick={handleUploadClick} className="p-2 text-slate-400 hover:text-emerald-400 transition-colors" title="Import"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"></path></svg></button>
          <button onClick={handleExportData} disabled={!currentTopic} className="p-2 text-slate-400 hover:text-indigo-400 transition-colors" title="Export"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg></button>
        </div>
      </header>

      <main className="flex-1 relative">
        {graphData.nodes.length > 0 ? (
          <Graph data={graphData} onNodeClick={handleNodeClick} isLoading={loading} />
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-black">
            <div className="max-w-md text-center space-y-8">
              <div className="relative inline-block">
                <div className="w-24 h-24 bg-sky-500/10 rounded-full animate-ping absolute inset-0"></div>
                <div className="w-24 h-24 bg-slate-800/80 rounded-full flex items-center justify-center border border-slate-700 relative">
                  <svg className="w-10 h-10 text-sky-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 11c0 3.517-1.009 6.799-2.753 9.571m-3.44-2.04l.054-.09A10.003 10.003 0 0014 4.13V4a2 2 0 114 0v.13c0 1.547.35 3.01.976 4.315a10.002 10.002 0 01-4.226 12.023l-.07.038" />
                  </svg>
                </div>
              </div>
              <div>
                <h2 className="text-3xl font-black text-slate-200 tracking-tight">COGNITIVE SYNERGY</h2>
                <p className="text-slate-500 mt-4 leading-relaxed text-sm">Enter a keyword to map the multiverse of its connections. Your exploration is automatically saved locally.</p>
              </div>
            </div>
          </div>
        )}

        {selectedNode && (
          <div className="absolute bottom-6 right-6 w-96 bg-slate-900/90 backdrop-blur-2xl border border-slate-700/50 rounded-3xl overflow-hidden shadow-2xl animate-in slide-in-from-right-4 duration-500 z-20">
            {selectedNode.wikiImage && (
              <div className="h-40 w-full relative">
                <img src={selectedNode.wikiImage} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-700" alt={selectedNode.label} />
                <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-transparent to-transparent"></div>
              </div>
            )}
            <div className="p-6">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="text-xl font-bold text-sky-400">{selectedNode.label}</h3>
                  <span className="text-[10px] uppercase font-black tracking-widest text-slate-500">Node Insight 0{selectedNode.group}</span>
                </div>
                <button onClick={() => setSelectedNode(null)} className="p-1 hover:bg-slate-800 rounded-lg text-slate-500 hover:text-white transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg></button>
              </div>
              <div className="space-y-4">
                <p className="text-sm text-slate-300 font-medium leading-relaxed italic border-l-2 border-sky-500/30 pl-4">
