                {selectedNode.wikiSummary && (
                  <div className="bg-slate-800/40 p-4 rounded-xl border border-slate-700/30">
                    <p className="text-xs text-slate-400 leading-relaxed line-clamp-4">
                      {selectedNode.wikiSummary}
