                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="p-4 bg-slate-950 border-t border-slate-900/50 flex justify-between items-center text-[10px] text-slate-700 font-bold uppercase tracking-widest px-8">
