        <div className="flex gap-10">
          <span className="flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]"></div> Logical Mesh Active</span>
          <span className="flex items-center gap-3"><div className={`w-2 h-2 rounded-full transition-all duration-500 ${autoExplode ? 'bg-sky-500 shadow-[0_0_12px_rgba(14,165,233,0.8)] animate-pulse' : 'bg-slate-800'}`}></div> Neural Pilot {autoExplode ? 'Engaged' : 'Standby'}</span>
        </div>
      </footer>
