import { SimulationNodeDatum, SimulationLinkDatum } from 'd3';

export interface GraphNode extends SimulationNodeDatum {
  id: string;
  label: string;
  group: number;
  description?: string;
  isExpanded?: boolean;
  depth: number;
  strength: number; // Added to prioritize explosion
  isFocused?: boolean;
  wikiUrl?: string;
  wikiSummary?: string;
  wikiImage?: string;
  aiImagePrompt?: string;
  x?: number;
  y?: number;
  vx?: number;
  vy?: number;
  fx?: number | null;
  fy?: number | null;
}

export interface GraphLink extends SimulationLinkDatum<GraphNode> {
  source: string | GraphNode;
  target: string | GraphNode;
  relationship?: string;
  strength?: number;
}

export interface GraphData {
  nodes: GraphNode[];
  links: GraphLink[];
}

export interface GeminiGraphResponse {
  nodes: Array<{ id: string; label: string; group: number; description: string; strength: number; aiImagePrompt?: string }>;
  links: Array<{ source: string; target: string; relationship: string; strength?: number }>;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GeminiGraphResponse, GraphNode } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const graphSchema = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING, description: "A unique short ID" },
          label: { type: Type.STRING, description: "Display name" },
          group: { type: Type.INTEGER, description: "Category group (1-5)" },
          description: { type: Type.STRING, description: "One-sentence deep insight" },
          strength: { type: Type.NUMBER, description: "Conceptual importance or 'weight' of this node (0.0 to 1.0)" },
          aiImagePrompt: { type: Type.STRING, description: "A highly descriptive image prompt for this concept" }
        },
        required: ["id", "label", "group", "description", "strength"]
      }
    },
    links: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Source node ID" },
          target: { type: Type.STRING, description: "Target node ID" },
          relationship: { type: Type.STRING, description: "Logical operator or predicate (e.g., 'Evolves into', 'Subsumes', 'Mitigates')" },
          strength: { type: Type.NUMBER, description: "Semantic weight 0-1" }
        },
        required: ["source", "target", "relationship"]
      }
    }
  },
  required: ["nodes", "links"]
};

export const generateInitialGraph = async (topic: string): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Architect a semantic neural map for: "${topic}". Identify the 5 most critical nodes that represent its core essence. Define complex logical links. Assign a 'strength' value to each node based on its foundational importance.`,
    config: {
      systemInstruction: "You are an AI Ontology Architect. Map reality with fractal precision. Each node must be a gateway to deeper understanding.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const expandNode = async (nodeLabel: string, contextTopic: string, existingNodes: string[]): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Perform a recursive deep-dive into "${nodeLabel}" within the field of "${contextTopic}". Uncover hidden patterns and obscure connections. Exclude: ${existingNodes.join(', ')}. Assign high strength values to nodes that represent breakthroughs or critical sub-components.`,
    config: {
      systemInstruction: "Expand knowledge fractally. Find connections that aren't obvious to humans. Use high-level academic and technical relationships.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const generateBriefing = async (topic: string, nodes: GraphNode[]): Promise<string> => {
  const concepts = nodes.map(n => `- **${n.label}** (Depth ${n.depth}, Strength ${n.strength}): ${n.description}`).join('\n');
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Synthesize a high-level briefing of the following conceptual map for "${topic}":\n${concepts}`,
    config: {
      systemInstruction: "Provide a strategic, high-level summary. Categorize concepts into primary, secondary, and tertiary layers of importance.",
    }
  });
  return response.text || "Synthesis error.";
};

export const chatWithNode = async (node: GraphNode, context: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `I am exploring "${context}". Tell me more about "${node.label}" (${node.description}). How does it relate to the bigger picture? Its conceptual strength is ${node.strength}.`,
  });
  return response.text || "Node is silent.";
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const STORAGE_KEY = 'knowledge_exploder_state_v3';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [currentTopic, setCurrentTopic] = useState('');
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);
  const [chatLog, setChatLog] = useState<string>('');

  const [briefing, setBriefing] = useState<string | null>(null);
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initial Load from LocalStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.graphData && Array.isArray(parsed.graphData.nodes)) {
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => nodeCache.current.set(n.id, n));
          setGraphData(parsed.graphData);
          setCurrentTopic(parsed.currentTopic || '');
          setTopic(parsed.currentTopic || '');
          setAutoExplode(!!parsed.autoExplode);
        }
      } catch (e) {
        console.error("Hydration failed:", e);
      }
    }
  }, []);

  // Sync to LocalStorage
  useEffect(() => {
    if (graphData.nodes.length === 0) return;
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));
    const state = { graphData: { nodes: graphData.nodes, links: serializableLinks }, currentTopic, autoExplode };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [graphData, currentTopic, autoExplode]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    localStorage.removeItem(STORAGE_KEY);
    try {
      const response = await gemini.generateInitialGraph(topic);
      processNewData(response, undefined, 0);
      setCurrentTopic(topic);
    } catch (error) {
      alert("Search synthesis failed.");
    } finally {
      setLoading(false);
    }
  };

  const clearSession = () => {
    if (window.confirm("Purge semantic map and reset neural pilot?")) {
      setGraphData({ nodes: [], links: [] });
      setTopic('');
      setCurrentTopic('');
      nodeCache.current.clear();
      setSelectedNode(null);
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode, depth: number = 0) => {
    let newNodesAdded: GraphNode[] = [];
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];

      newData.nodes.forEach(node => {
        if (!nodeCache.current.has(node.id)) {
          const newNode: GraphNode = { 
            ...node,
            depth,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 60 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 60 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
          newNodesAdded.push(newNode);
        }
      });

      newData.links.forEach(link => {
        if (!nodeCache.current.has(link.source) || !nodeCache.current.has(link.target)) return;
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists) updatedLinks.push(link as GraphLink);
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });

    // Intelligent Auto-Explode selection
    if (autoExplode && newNodesAdded.length > 0 && !loading) {
      const timer = setTimeout(() => {
          // Prioritize by Depth (fractal expansion) and Strength (semantic weight)
          // Scoring formula: (depth * 2) + (strength * 5)
          // We prioritize nodes that are deeper in the tree but also high in semantic importance
          const prioritized = [...newNodesAdded].sort((a, b) => {
            const scoreA = (a.depth * 2) + (a.strength * 5);
            const scoreB = (b.depth * 2) + (b.strength * 5);
            return scoreB - scoreA;
          });

          const next = prioritized[0];
          handleNodeClick(next);
      }, 4000);
      return () => clearTimeout(timer);
    }
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    setChatLog('Neural analyzer engaging...');

    // Fetch multimedia
    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    // AI Insight
    gemini.chatWithNode(node, currentTopic).then(msg => {
        if (selectedNode?.id === node.id) setChatLog(msg);
    });

    if (node.isExpanded) return;
    setLoading(true);
    try {
      const existingLabels = [...nodeCache.current.values()].map(n => n.label);
      const response = await gemini.expandNode(node.label, currentTopic, existingLabels);
      node.isExpanded = true;
      processNewData(response, node, (node.depth || 0) + 1);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, [currentTopic, autoExplode, selectedNode]);

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 font-sans selection:bg-sky-500/30 overflow-hidden">
      <input type="file" ref={fileInputRef} onChange={(e) => {}} accept=".json" className="hidden" />

      {/* Futuristic Header */}
      <header className="z-10 bg-slate-900/40 backdrop-blur-2xl border-b border-slate-800/50 p-4 flex flex-col md:flex-row items-center gap-6">
        <div className="flex items-center gap-4 group">
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-2xl transition-all duration-700 ${autoExplode ? 'bg-sky-500 shadow-sky-500/50 rotate-90 scale-110' : 'bg-slate-800 shadow-black'}`}>
            <svg className={`w-7 h-7 ${autoExplode ? 'animate-pulse text-white' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
            </svg>
          </div>
          <div>
            <h1 className="text-xl font-black tracking-[0.2em] italic text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-indigo-500">KNOWLEDGE EX</h1>
            <div className="flex items-center gap-2">
                <span className="text-[10px] text-slate-500 uppercase font-black tracking-widest">Neural Autonomy Core</span>
                <div className={`w-1.5 h-1.5 rounded-full ${autoExplode ? 'bg-sky-400 animate-ping' : 'bg-slate-700'}`}></div>
            </div>
          </div>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-2xl w-full flex items-center gap-2 relative">
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Seed fractal exploration..."
            className="flex-1 bg-slate-900/50 border-2 border-slate-800/50 rounded-2xl px-6 py-3 focus:outline-none focus:border-sky-500/50 focus:ring-4 focus:ring-sky-500/10 transition-all placeholder:text-slate-700 text-sm font-medium"
          />
          <button type="submit" disabled={loading} className="bg-sky-600 hover:bg-sky-500 disabled:opacity-20 text-white font-black px-8 py-3 rounded-2xl text-xs tracking-widest transition-all active:scale-95 shadow-xl shadow-sky-900/20">
            IGNITE
          </button>
        </form>

        <div className="flex items-center gap-4">
          <label className="flex items-center gap-3 cursor-pointer select-none px-4 py-2 bg-slate-900/50 border border-slate-800 rounded-2xl hover:bg-slate-800 transition-colors">
            <span className={`text-[10px] font-black uppercase tracking-widest ${autoExplode ? 'text-sky-400' : 'text-slate-500'}`}>Pilot</span>
            <div className="relative" onClick={() => setAutoExplode(!autoExplode)}>
                <div className={`w-10 h-5 rounded-full transition-colors ${autoExplode ? 'bg-sky-600' : 'bg-slate-700'}`}></div>
                <div className={`absolute top-1 left-1 w-3 h-3 rounded-full bg-white transition-transform ${autoExplode ? 'translate-x-5' : ''}`}></div>
            </div>
          </label>

          <div className="h-8 w-px bg-slate-800"></div>

          <div className="flex items-center gap-1">
            <button onClick={clearSession} className="p-3 text-slate-500 hover:text-red-400 transition-colors" title="Purge Map"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg></button>
            <button onClick={() => setIsBriefingLoading(true)} className="p-3 text-slate-500 hover:text-sky-400 transition-colors" title="AI Briefing"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg></button>
          </div>
        </div>
