import { SimulationNodeDatum, SimulationLinkDatum } from 'd3';

export interface GraphNode extends SimulationNodeDatum {
  id: string;
  label: string;
  group: number;
  description?: string;
  isExpanded?: boolean;
  depth: number;
  strength: number;
  isTargeted?: boolean; // New: Visual indicator for the "Neural Pilot" target
  isFocused?: boolean;
  wikiUrl?: string;
  wikiSummary?: string;
  wikiImage?: string;
  aiImagePrompt?: string;
  x?: number;
  y?: number;
  vx?: number;
  vy?: number;
  fx?: number | null;
  fy?: number | null;
}

export interface GraphLink extends SimulationLinkDatum<GraphNode> {
  source: string | GraphNode;
  target: string | GraphNode;
  relationship?: string;
  strength?: number;
}

export interface GraphData {
  nodes: GraphNode[];
  links: GraphLink[];
}

export interface GeminiGraphResponse {
  nodes: Array<{ id: string; label: string; group: number; description: string; strength: number; aiImagePrompt?: string }>;
  links: Array<{ source: string; target: string; relationship: string; strength?: number }>;
}

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { GraphNode, GraphLink, GraphData } from '../types';

interface GraphProps {
  data: GraphData;
  onNodeClick: (node: GraphNode) => void;
  isLoading: boolean;
}

const Graph: React.FC<GraphProps> = ({ data, onNodeClick, isLoading }) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<SVGGElement>(null);
  const simulationRef = useRef<d3.Simulation<GraphNode, GraphLink> | null>(null);

  const colors = ['#0ea5e9', '#10b981', '#f43f5e', '#f59e0b', '#8b5cf6', '#ec4899'];

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    const width = window.innerWidth;
    const height = window.innerHeight;

    const simulation = d3.forceSimulation<GraphNode>()
      .force('link', d3.forceLink<GraphNode, GraphLink>().id(d => d.id).distance(d => 180 - (d.source as GraphNode).depth * 12).strength(0.8))
      .force('charge', d3.forceManyBody().strength(d => -700 - d.depth * 150))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(80));

    simulationRef.current = simulation;

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.05, 5])
      .on('zoom', (event) => {
        d3.select(containerRef.current).attr('transform', event.transform);
        const k = event.transform.k;
        d3.selectAll('.edge-label').style('opacity', k > 0.6 ? 0.6 : 0);
        d3.selectAll('.node-label').style('font-size', `${Math.max(12, 14 / k)}px`);
      });

    svg.call(zoom);

    return () => { simulation.stop(); };
  }, []);

  useEffect(() => {
    if (!simulationRef.current || !containerRef.current) return;
    const simulation = simulationRef.current;
    const container = d3.select(containerRef.current);

    simulation.nodes(data.nodes);
    const linkForce = simulation.force<d3.ForceLink<GraphNode, GraphLink>>('link');
    if (linkForce) linkForce.links(data.links);

    // Links Rendering
    let linkGroup = container.selectAll<SVGGElement, GraphLink>('.link-group')
      .data(data.links, d => `${(d.source as any).id || d.source}-${(d.target as any).id || d.target}`);

    linkGroup.exit().remove();
    const linkEnter = linkGroup.enter().append('g').attr('class', 'link-group');

    linkEnter.append('line')
      .attr('class', 'link')
      .attr('stroke', '#334155')
      .attr('stroke-width', d => (d.strength || 0.5) * 4)
      .attr('stroke-dasharray', d => d.strength && d.strength > 0.8 ? '0' : '5,5');

    linkEnter.append('text')
      .attr('class', 'edge-label')
      .attr('text-anchor', 'middle')
      .attr('fill', '#64748b')
      .attr('font-size', '10px')
      .attr('font-weight', 'bold')
      .attr('dy', -8)
      .text(d => d.relationship || '');

    linkGroup = linkEnter.merge(linkGroup);

    // Nodes Rendering
    let node = container.selectAll<SVGGElement, GraphNode>('.node-group')
      .data(data.nodes, d => d.id);

    node.exit().remove();
    const nodeEnter = node.enter()
      .append('g')
      .attr('class', 'node-group')
      .on('click', (event, d) => {
        event.stopPropagation();
        onNodeClick(d);
      })
      .call(d3.drag<SVGGElement, GraphNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x; d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x; d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null; d.fy = null;
        })
      );

    // Glow filter
    const defs = container.select('defs');
    if (defs.empty()) {
        const d = container.append('defs');
        const filter = d.append('filter').attr('id', 'glow');
        filter.append('feGaussianBlur').attr('stdDeviation', '3.5').attr('result', 'coloredBlur');
        const merge = filter.append('feMerge');
        merge.append('feMergeNode').attr('in', 'coloredBlur');
        merge.append('feMergeNode').attr('in', 'SourceGraphic');
    }

    // Target Pulse Ring (for Neural Pilot)
    nodeEnter.append('circle')
      .attr('class', 'target-ring')
      .attr('r', 45)
      .attr('fill', 'none')
      .attr('stroke', '#0ea5e9')
      .attr('stroke-width', 2)
      .attr('stroke-dasharray', '4,4')
      .style('opacity', 0);

    nodeEnter.append('circle')
      .attr('class', 'node-main-circle')
      .attr('r', d => 24 - (d.depth * 2))
      .attr('fill', d => colors[d.group % colors.length])
      .attr('stroke', '#020617')
      .attr('stroke-width', 3)
      .style('filter', 'url(#glow)')
      .attr('class', 'transition-all duration-500 hover:brightness-125 cursor-pointer');

    nodeEnter.append('text')
      .attr('class', 'node-label')
      .attr('dx', 32)
      .attr('dy', '.35em')
      .attr('fill', '#f8fafc')
      .attr('font-weight', '700')
      .style('pointer-events', 'none')
      .style('text-shadow', '0 2px 8px rgba(0,0,0,1)');

    node = nodeEnter.merge(node);
    node.select('text').text(d => d.label);

    // Update visual states based on data properties
    node.select('.node-main-circle')
      .attr('fill', d => d.isExpanded ? colors[d.group % colors.length] : '#1e293b')
      .style('stroke', d => d.isTargeted ? '#0ea5e9' : '#020617')
      .style('stroke-width', d => d.isTargeted ? 6 : 3);

    node.select('.target-ring')
      .style('opacity', d => d.isTargeted ? 0.8 : 0)
      .attr('class', d => d.isTargeted ? 'target-ring animate-pulse' : 'target-ring');

    simulation.on('tick', () => {
      linkGroup.select('line')
        .attr('x1', d => (d.source as any).x)
        .attr('y1', d => (d.source as any).y)
        .attr('x2', d => (d.target as any).x)
        .attr('y2', d => (d.target as any).y);

      linkGroup.select('text')
        .attr('x', d => ((d.source as any).x + (d.target as any).x) / 2)
        .attr('y', d => ((d.source as any).y + (d.target as any).y) / 2);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    simulation.alpha(0.6).restart();
  }, [data, onNodeClick]);

  return (
    <div className="relative w-full h-full bg-[#020617] overflow-hidden">
      <svg ref={svgRef} className="w-full h-full" style={{ touchAction: 'none' }}>
        <g ref={containerRef} />
      </svg>
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-sm pointer-events-none">
          <div className="flex flex-col items-center gap-4 bg-slate-900/90 p-10 rounded-[2rem] border-2 border-sky-500/20 shadow-[0_0_50px_rgba(14,165,233,0.2)]">
            <div className="relative">
                <div className="w-16 h-16 border-4 border-sky-500 border-t-transparent rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                    <div className="w-4 h-4 bg-sky-500 rounded-full animate-pulse"></div>
                </div>
            </div>
            <p className="text-sky-400 font-black tracking-widest uppercase text-[10px] animate-pulse">Fractal Expansion Active</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Graph;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const STORAGE_KEY = 'knowledge_exploder_state_v4';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [currentTopic, setCurrentTopic] = useState('');
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);
  const [chatLog, setChatLog] = useState<string>('');

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const pilotTimerRef = useRef<number | null>(null);

  // Initial Load from LocalStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.graphData && Array.isArray(parsed.graphData.nodes)) {
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => {
            // Ensure nodes don't stay 'targeted' on reload
            n.isTargeted = false;
            nodeCache.current.set(n.id, n);
          });
          setGraphData(parsed.graphData);
          setCurrentTopic(parsed.currentTopic || '');
          setTopic(parsed.currentTopic || '');
          setAutoExplode(!!parsed.autoExplode);
        }
      } catch (e) {
        console.error("Hydration failed:", e);
      }
    }
  }, []);

  // Sync to LocalStorage
  useEffect(() => {
    if (graphData.nodes.length === 0) return;
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));
    const state = { 
      graphData: { 
        nodes: graphData.nodes.map(n => ({ ...n, isTargeted: false })), 
        links: serializableLinks 
      }, 
      currentTopic, 
      autoExplode 
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [graphData, currentTopic, autoExplode]);

  // The Neural Pilot Brain: Intelligent orchestration
  useEffect(() => {
    if (autoExplode && !loading && graphData.nodes.length > 0) {
      // Clear existing timers to avoid multiple pilots
      if (pilotTimerRef.current) clearTimeout(pilotTimerRef.current);

      pilotTimerRef.current = window.setTimeout(() => {
        // Find candidates: unexpanded nodes
        const candidates = graphData.nodes.filter(n => !n.isExpanded);

        if (candidates.length === 0) {
          // If all expanded, maybe we should "re-explode" nodes with very high strength
          // but for now let's just wait or do nothing
          return;
        }

        // SCORING ALGORITHM: Prioritize Depth and Strength
        // Score = (depth * 1.5) + (strength * 10) + random_jitter
        // High strength foundational nodes get picked early, 
        // but as depth increases, deeper "fractal" nodes get prioritized.
        const prioritized = [...candidates].sort((a, b) => {
          const scoreA = (a.depth * 1.5) + (a.strength * 10) + (Math.random() * 2);
          const scoreB = (b.depth * 1.5) + (b.strength * 10) + (Math.random() * 2);
          return scoreB - scoreA;
        });

        const next = prioritized[0];

        // Visual Feedback: Target the node first
        setGraphData(prev => ({
          ...prev,
          nodes: prev.nodes.map(n => ({ ...n, isTargeted: n.id === next.id }))
        }));

        // Small delay before actual explosion for UX "suspense"
        setTimeout(() => {
          if (autoExplode && !loading) {
            handleNodeClick(next);
          }
        }, 1500);

      }, 4000);
    }

    return () => {
      if (pilotTimerRef.current) clearTimeout(pilotTimerRef.current);
    };
  }, [autoExplode, loading, graphData.nodes.length, currentTopic]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    localStorage.removeItem(STORAGE_KEY);
    try {
      const response = await gemini.generateInitialGraph(topic);
      processNewData(response, undefined, 0);
      setCurrentTopic(topic);
    } catch (error) {
      alert("Search synthesis failed.");
    } finally {
      setLoading(false);
    }
  };

  const clearSession = () => {
    if (window.confirm("Purge semantic map and reset neural pilot?")) {
      setGraphData({ nodes: [], links: [] });
      setTopic('');
      setCurrentTopic('');
      nodeCache.current.clear();
      setSelectedNode(null);
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode, depth: number = 0) => {
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];

      // Remove targeted state from everyone as we update
      updatedNodes.forEach(n => n.isTargeted = false);

      newData.nodes.forEach(node => {
        if (!nodeCache.current.has(node.id)) {
          const newNode: GraphNode = { 
            ...node,
            depth,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 80 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 80 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
        }
      });

      newData.links.forEach(link => {
        if (!nodeCache.current.has(link.source) || !nodeCache.current.has(link.target)) return;
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists) updatedLinks.push(link as GraphLink);
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    setChatLog('Neural analyzer engaging...');

    // Fetch multimedia
    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    // AI Insight
    gemini.chatWithNode(node, currentTopic).then(msg => {
        if (selectedNode?.id === node.id || nodeCache.current.get(node.id)?.isFocused) setChatLog(msg);
    });

    if (node.isExpanded) return;

    setLoading(true);
    try {
      const existingLabels = [...nodeCache.current.values()].map(n => n.label);
      const response = await gemini.expandNode(node.label, currentTopic, existingLabels);

      const cachedNode = nodeCache.current.get(node.id);
      if (cachedNode) cachedNode.isExpanded = true;

      processNewData(response, node, (node.depth || 0) + 1);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, [currentTopic, selectedNode]);

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 font-sans selection:bg-sky-500/30 overflow-hidden">
      <input type="file" ref={fileInputRef} onChange={() => {}} accept=".json" className="hidden" />

      {/* Futuristic Header */}
      <header className="z-10 bg-slate-900/40 backdrop-blur-2xl border-b border-slate-800/50 p-4 flex flex-col md:flex-row items-center gap-6">
        <div className="flex items-center gap-4 group">
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-2xl transition-all duration-700 ${autoExplode ? 'bg-sky-500 shadow-sky-500/50 rotate-90 scale-110' : 'bg-slate-800 shadow-black'}`}>
            <svg className={`w-7 h-7 ${autoExplode ? 'animate-pulse text-white' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-xl font-black tracking-[0.2em] italic text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-indigo-500">KNOWLEDGE EX</h1>
            <div className="flex items-center gap-2">
                <span className="text-[10px] text-slate-500 uppercase font-black tracking-widest">Autonomous Facilitation v5</span>
                <div className={`w-1.5 h-1.5 rounded-full ${autoExplode ? 'bg-sky-400 animate-ping' : 'bg-slate-700'}`}></div>
            </div>
          </div>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-2xl w-full flex items-center gap-2 relative">
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Seed fractal exploration..."
            className="flex-1 bg-slate-900/50 border-2 border-slate-800/50 rounded-2xl px-6 py-3 focus:outline-none focus:border-sky-500/50 focus:ring-4 focus:ring-sky-500/10 transition-all placeholder:text-slate-700 text-sm font-medium"
          />
          <button type="submit" disabled={loading} className="bg-sky-600 hover:bg-sky-500 disabled:opacity-20 text-white font-black px-8 py-3 rounded-2xl text-xs tracking-widest transition-all active:scale-95 shadow-xl shadow-sky-900/20">
            IGNITE
          </button>
        </form>

        <div className="flex items-center gap-4">
          <label className="flex items-center gap-3 cursor-pointer select-none px-4 py-2 bg-slate-900/50 border border-slate-800 rounded-2xl hover:bg-slate-800 transition-colors">
            <span className={`text-[10px] font-black uppercase tracking-widest ${autoExplode ? 'text-sky-400' : 'text-slate-500'}`}>Pilot</span>
            <div className="relative" onClick={() => setAutoExplode(!autoExplode)}>
                <div className={`w-10 h-5 rounded-full transition-colors ${autoExplode ? 'bg-sky-600' : 'bg-slate-700'}`}></div>
                <div className={`absolute top-1 left-1 w-3 h-3 rounded-full bg-white transition-transform ${autoExplode ? 'translate-x-5' : ''}`}></div>
            </div>
          </label>

          <div className="h-8 w-px bg-slate-800"></div>

          <div className="flex items-center gap-1">
            <button onClick={clearSession} className="p-3 text-slate-500 hover:text-red-400 transition-colors" title="Purge Map"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg></button>
          </div>
        </div>
      </header>

      <main className="flex-1 relative">
        {graphData.nodes.length > 0 ? (
          <Graph data={graphData} onNodeClick={handleNodeClick} isLoading={loading} />
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-black">
            <div className="max-w-xl text-center space-y-12">
              <div className="relative inline-block">
                <div className="w-40 h-40 bg-sky-500/10 rounded-[3rem] animate-pulse absolute inset-0 blur-2xl"></div>
                <div className="w-32 h-32 bg-slate-900 border border-slate-800 rounded-[2rem] flex items-center justify-center relative shadow-2xl">
                    <svg className="w-16 h-16 text-sky-500/50" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2-1l-2-1m2 1v2.5M14 4l-2 1m0 0L10 4m2 1v2.5M4 7l2-1M4 7l2 1M4 7v2.5M10 21l2-1m0 0l2 1m-2-1v-2.5M6 18l-2-1m2 1l2-1m-2 1v-2.5" />
                    </svg>
                </div>
              </div>
              <div className="space-y-6">
                <h2 className="text-4xl font-black text-slate-100 tracking-tighter uppercase italic">Anticipatory Cognition</h2>
                <p className="text-slate-500 text-lg font-medium max-w-lg mx-auto leading-relaxed">
                  Toggle <span className="text-sky-400 underline decoration-sky-500/30">Neural Pilot</span> for autonomous facilitate expansion. The system prioritizes core strength and fractal depth.
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Dynamic Insight Overlay */}
        {selectedNode && (
          <div className="absolute top-6 right-6 w-[420px] max-h-[calc(100vh-120px)] bg-slate-900/80 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] overflow-hidden shadow-[0_32px_64px_-16px_rgba(0,0,0,0.8)] animate-in slide-in-from-right-10 duration-700 z-20 flex flex-col">
            <div className="relative group">
                {selectedNode.wikiImage ? (
                    <img src={selectedNode.wikiImage} className="w-full h-56 object-cover brightness-75 group-hover:brightness-100 transition-all duration-1000" alt={selectedNode.label} />
                ) : (
                    <div className="h-56 bg-gradient-to-br from-slate-800 to-slate-900 flex items-center justify-center overflow-hidden">
                        <div className="text-[8rem] font-black text-white/5 absolute -bottom-10 -right-10 italic uppercase select-none">{selectedNode.label}</div>
                        <svg className="w-16 h-16 text-slate-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                    </div>
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-transparent to-transparent"></div>
                <button onClick={() => setSelectedNode(null)} className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black rounded-full text-white/50 hover:text-white transition-all backdrop-blur-md">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
