            </div>

            <div className="p-8 flex-1 overflow-y-auto space-y-6">
              <div>
                <div className="flex items-center gap-3 mb-1">
                    <span className="text-[10px] font-black text-sky-500 uppercase tracking-widest px-2 py-1 bg-sky-500/10 rounded-lg">Level 0{selectedNode.depth}</span>
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Sector {selectedNode.group}</span>
                    <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Weight: {selectedNode.strength.toFixed(2)}</span>
                </div>
                <h3 className="text-3xl font-black text-white italic tracking-tighter">{selectedNode.label}</h3>
              </div>

              <div className="space-y-4">
                <p className="text-slate-300 font-medium leading-relaxed border-l-4 border-sky-500/50 pl-6 py-2 bg-sky-500/5 rounded-r-xl">
                  {selectedNode.description}
                </p>

                <div className="p-6 bg-black/40 border border-white/5 rounded-3xl space-y-3">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                        <div className="w-1 h-1 bg-sky-500 rounded-full"></div>
                        Neural Insight
                    </h4>
                    <p className="text-xs text-slate-400 leading-relaxed font-medium">
                        {chatLog || 'Synthesizing specific connections...'}
                    </p>
                </div>

                {selectedNode.wikiSummary && (
                  <div className="space-y-4">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                        <div className="w-1 h-1 bg-emerald-500 rounded-full"></div>
                        Wikipedia Baseline
                    </h4>
                    <p className="text-xs text-slate-400 leading-relaxed italic">
                      {selectedNode.wikiSummary}
                    </p>
                    <a href={selectedNode.wikiUrl} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 text-[10px] text-sky-400 font-black uppercase tracking-widest hover:text-sky-300 transition-colors">
                        Source Terminal <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
                    </a>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="p-4 bg-[#01040a] border-t border-slate-900 flex justify-between items-center text-[10px] text-slate-600 font-black uppercase tracking-[0.3em] px-10">
        <div className="flex items-center gap-6">
            <span>Logic: Gemini 3 Pro</span>
            <div className="w-1 h-1 bg-slate-800 rounded-full"></div>
            <span>Nodes: {graphData.nodes.length}</span>
            <div className="w-1 h-1 bg-slate-800 rounded-full"></div>
            <span>Links: {graphData.links.length}</span>
        </div>
        <div className="flex gap-10">
          <span className="flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]"></div> Semantic Resonance Active</span>
          <span className="flex items-center gap-3"><div className={`w-2 h-2 rounded-full transition-all duration-500 ${autoExplode ? 'bg-sky-500 shadow-[0_0_12px_rgba(14,165,233,0.8)] animate-pulse' : 'bg-slate-800'}`}></div> Neural Pilot {autoExplode ? 'Orchestrating' : 'Standby'}</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const STORAGE_KEY = 'knowledge_exploder_state_v4';

const App: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [currentTopic, setCurrentTopic] = useState('');
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);
  const [chatLog, setChatLog] = useState<string>('');

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const pilotTimerRef = useRef<number | null>(null);

  // Initial Load from LocalStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.graphData && Array.isArray(parsed.graphData.nodes)) {
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => {
            n.isTargeted = false;
            nodeCache.current.set(n.id, n);
          });
          setGraphData(parsed.graphData);
          setCurrentTopic(parsed.currentTopic || '');
          setTopic(parsed.currentTopic || '');
          setAutoExplode(!!parsed.autoExplode);
        }
      } catch (e) {
        console.error("Hydration failed:", e);
      }
    }
  }, []);

  // Sync to LocalStorage
  useEffect(() => {
    if (graphData.nodes.length === 0) return;
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));
    const state = { 
      graphData: { 
        nodes: graphData.nodes.map(n => ({ ...n, isTargeted: false })), 
        links: serializableLinks 
      }, 
      currentTopic, 
      autoExplode 
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }, [graphData, currentTopic, autoExplode]);

  // The Neural Pilot Brain
  useEffect(() => {
    if (autoExplode && !loading && graphData.nodes.length > 0) {
      if (pilotTimerRef.current) clearTimeout(pilotTimerRef.current);

      pilotTimerRef.current = window.setTimeout(() => {
        const candidates = graphData.nodes.filter(n => !n.isExpanded);
        if (candidates.length === 0) return;

        const prioritized = [...candidates].sort((a, b) => {
          const scoreA = (a.depth * 1.5) + (a.strength * 10) + (Math.random() * 2);
          const scoreB = (b.depth * 1.5) + (b.strength * 10) + (Math.random() * 2);
          return scoreB - scoreA;
        });

        const next = prioritized[0];

        setGraphData(prev => ({
          ...prev,
          nodes: prev.nodes.map(n => ({ ...n, isTargeted: n.id === next.id }))
        }));

        setTimeout(() => {
          if (autoExplode && !loading) {
            handleNodeClick(next);
          }
        }, 1500);

      }, 4000);
    }

    return () => {
      if (pilotTimerRef.current) clearTimeout(pilotTimerRef.current);
    };
  }, [autoExplode, loading, graphData.nodes.length, currentTopic]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    localStorage.removeItem(STORAGE_KEY);
    try {
      const response = await gemini.generateInitialGraph(topic);
      processNewData(response, undefined, 0);
      setCurrentTopic(topic);
    } catch (error) {
      alert("Search synthesis failed.");
    } finally {
      setLoading(false);
    }
  };

  const clearSession = () => {
    if (window.confirm("Purge semantic map and reset neural pilot?")) {
      setGraphData({ nodes: [], links: [] });
      setTopic('');
      setCurrentTopic('');
      nodeCache.current.clear();
      setSelectedNode(null);
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  const handleExportData = () => {
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));

    const dataToExport = {
      graphData: {
        nodes: graphData.nodes.map(n => ({ ...n, isTargeted: false })),
        links: serializableLinks
      },
      currentTopic,
      version: "KnowledgeExploder_v4"
    };

    const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `neural-map-${currentTopic.replace(/\s+/g, '-').toLowerCase() || 'export'}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parsed = JSON.parse(content);
        if (parsed.graphData && Array.isArray(parsed.graphData.nodes)) {
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => {
            n.isTargeted = false;
            nodeCache.current.set(n.id, n);
          });
          setGraphData(parsed.graphData);
          setCurrentTopic(parsed.currentTopic || '');
          setTopic(parsed.currentTopic || '');
          setSelectedNode(null);
        } else {
          alert("Invalid map format.");
        }
      } catch (err) {
        alert("Failed to parse map file.");
      }
    };
    reader.readAsText(file);
    event.target.value = ''; // Reset input
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode, depth: number = 0) => {
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];

      updatedNodes.forEach(n => n.isTargeted = false);

      newData.nodes.forEach(node => {
        if (!nodeCache.current.has(node.id)) {
          const newNode: GraphNode = { 
            ...node,
            depth,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 80 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 80 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
        }
      });

      newData.links.forEach(link => {
        if (!nodeCache.current.has(link.source) || !nodeCache.current.has(link.target)) return;
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists) updatedLinks.push(link as GraphLink);
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    setChatLog('Neural analyzer engaging...');

    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    gemini.chatWithNode(node, currentTopic).then(msg => {
        if (selectedNode?.id === node.id || nodeCache.current.get(node.id)?.isFocused) setChatLog(msg);
    });

    if (node.isExpanded) return;

    setLoading(true);
    try {
      const existingLabels = [...nodeCache.current.values()].map(n => n.label);
      const response = await gemini.expandNode(node.label, currentTopic, existingLabels);

      const cachedNode = nodeCache.current.get(node.id);
      if (cachedNode) cachedNode.isExpanded = true;

      processNewData(response, node, (node.depth || 0) + 1);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  }, [currentTopic, selectedNode]);

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 font-sans selection:bg-sky-500/30 overflow-hidden">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        accept=".json" 
        className="hidden" 
      />

      {/* Futuristic Header */}
      <header className="z-10 bg-slate-900/40 backdrop-blur-2xl border-b border-slate-800/50 p-4 flex flex-col md:flex-row items-center gap-6">
        <div className="flex items-center gap-4 group">
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-2xl transition-all duration-700 ${autoExplode ? 'bg-sky-500 shadow-sky-500/50 rotate-90 scale-110' : 'bg-slate-800 shadow-black'}`}>
            <svg className={`w-7 h-7 ${autoExplode ? 'animate-pulse text-white' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-xl font-black tracking-[0.2em] italic text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-indigo-500">KNOWLEDGE EX</h1>
            <div className="flex items-center gap-2">
                <span className="text-[10px] text-slate-500 uppercase font-black tracking-widest">Autonomous Facilitation v5</span>
                <div className={`w-1.5 h-1.5 rounded-full ${autoExplode ? 'bg-sky-400 animate-ping' : 'bg-slate-700'}`}></div>
            </div>
          </div>
        </div>

        <form onSubmit={handleSearch} className="flex-1 max-w-2xl w-full flex items-center gap-2 relative">
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="Seed fractal exploration..."
            className="flex-1 bg-slate-900/50 border-2 border-slate-800/50 rounded-2xl px-6 py-3 focus:outline-none focus:border-sky-500/50 focus:ring-4 focus:ring-sky-500/10 transition-all placeholder:text-slate-700 text-sm font-medium"
          />
          <button type="submit" disabled={loading} className="bg-sky-600 hover:bg-sky-500 disabled:opacity-20 text-white font-black px-8 py-3 rounded-2xl text-xs tracking-widest transition-all active:scale-95 shadow-xl shadow-sky-900/20">
            IGNITE
          </button>
        </form>

        <div className="flex items-center gap-4">
          <label className="flex items-center gap-3 cursor-pointer select-none px-4 py-2 bg-slate-900/50 border border-slate-800 rounded-2xl hover:bg-slate-800 transition-colors">
            <span className={`text-[10px] font-black uppercase tracking-widest ${autoExplode ? 'text-sky-400' : 'text-slate-500'}`}>Pilot</span>
            <div className="relative" onClick={() => setAutoExplode(!autoExplode)}>
                <div className={`w-10 h-5 rounded-full transition-colors ${autoExplode ? 'bg-sky-600' : 'bg-slate-700'}`}></div>
                <div className={`absolute top-1 left-1 w-3 h-3 rounded-full bg-white transition-transform ${autoExplode ? 'translate-x-5' : ''}`}></div>
            </div>
          </label>

          <div className="h-8 w-px bg-slate-800"></div>

          <div className="flex items-center gap-1">
            <button onClick={handleUploadClick} className="p-3 text-slate-500 hover:text-emerald-400 transition-colors" title="Import Map">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"></path>
              </svg>
            </button>
            <button onClick={handleExportData} disabled={!currentTopic} className="p-3 text-slate-500 hover:text-indigo-400 transition-colors" title="Export Map">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path>
              </svg>
            </button>
            <button onClick={clearSession} className="p-3 text-slate-500 hover:text-red-400 transition-colors" title="Purge Map">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path>
              </svg>
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 relative">
        {graphData.nodes.length > 0 ? (
          <Graph data={graphData} onNodeClick={handleNodeClick} isLoading={loading} />
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-black">
            <div className="max-w-xl text-center space-y-12">
              <div className="relative inline-block">
                <div className="w-40 h-40 bg-sky-500/10 rounded-[3rem] animate-pulse absolute inset-0 blur-2xl"></div>
                <div className="w-32 h-32 bg-slate-900 border border-slate-800 rounded-[2rem] flex items-center justify-center relative shadow-2xl">
                    <svg className="w-16 h-16 text-sky-500/50" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M14 10l-2 1m0 0l-2-1m2 1v2.5M20 7l-2 1m2-1l-2-1m2 1v2.5M14 4l-2 1m0 0L10 4m2 1v2.5M4 7l2-1M4 7l2 1M4 7v2.5M10 21l2-1m0 0l2 1m-2-1v-2.5M6 18l-2-1m2 1l2-1m-2 1v-2.5" />
                    </svg>
                </div>
              </div>
              <div className="space-y-6">
                <h2 className="text-4xl font-black text-slate-100 tracking-tighter uppercase italic">Anticipatory Cognition</h2>
                <p className="text-slate-500 text-lg font-medium max-w-lg mx-auto leading-relaxed">
                  Toggle <span className="text-sky-400 underline decoration-sky-500/30">Neural Pilot</span> for autonomous facilitate expansion. The system prioritizes core strength and fractal depth.
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Dynamic Insight Overlay */}
        {selectedNode && (
          <div className="absolute top-6 right-6 w-[420px] max-h-[calc(100vh-120px)] bg-slate-900/80 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] overflow-hidden shadow-[0_32px_64px_-16px_rgba(0,0,0,0.8)] animate-in slide-in-from-right-10 duration-700 z-20 flex flex-col">
            <div className="relative group">
                {selectedNode.wikiImage ? (
                    <img src={selectedNode.wikiImage} className="w-full h-56 object-cover brightness-75 group-hover:brightness-100 transition-all duration-1000" alt={selectedNode.label} />
                ) : (
                    <div className="h-56 bg-gradient-to-br from-slate-800 to-slate-900 flex items-center justify-center overflow-hidden">
                        <div className="text-[8rem] font-black text-white/5 absolute -bottom-10 -right-10 italic uppercase select-none">{selectedNode.label}</div>
                        <svg className="w-16 h-16 text-slate-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                    </div>
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-transparent to-transparent"></div>
                <button onClick={() => setSelectedNode(null)} className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black rounded-full text-white/50 hover:text-white transition-all backdrop-blur-md">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
                </button>
            </div>

            <div className="p-8 flex-1 overflow-y-auto space-y-6">
              <div>
                <div className="flex items-center gap-3 mb-1">
                    <span className="text-[10px] font-black text-sky-500 uppercase tracking-widest px-2 py-1 bg-sky-500/10 rounded-lg">Level 0{selectedNode.depth}</span>
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Sector {selectedNode.group}</span>
                    <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Weight: {selectedNode.strength?.toFixed(2) || '0.00'}</span>
                </div>
                <h3 className="text-3xl font-black text-white italic tracking-tighter">{selectedNode.label}</h3>
              </div>

              <div className="space-y-4">
                <p className="text-slate-300 font-medium leading-relaxed border-l-4 border-sky-500/50 pl-6 py-2 bg-sky-500/5 rounded-r-xl">
                  {selectedNode.description}
                </p>

                <div className="p-6 bg-black/40 border border-white/5 rounded-3xl space-y-3">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                        <div className="w-1 h-1 bg-sky-500 rounded-full"></div>
                        Neural Insight
                    </h4>
                    <p className="text-xs text-slate-400 leading-relaxed font-medium">
                        {chatLog || 'Synthesizing specific connections...'}
                    </p>
                </div>

                {selectedNode.wikiSummary && (
                  <div className="space-y-4">
                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                        <div className="w-1 h-1 bg-emerald-500 rounded-full"></div>
                        Wikipedia Baseline
                    </h4>
                    <p className="text-xs text-slate-400 leading-relaxed italic">
                      {selectedNode.wikiSummary}
                    </p>
                    <a href={selectedNode.wikiUrl} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-2 text-[10px] text-sky-400 font-black uppercase tracking-widest hover:text-sky-300 transition-colors">
                        Source Terminal <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
                    </a>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="p-4 bg-[#01040a] border-t border-slate-900 flex justify-between items-center text-[10px] text-slate-600 font-black uppercase tracking-[0.3em] px-10">
        <div className="flex items-center gap-6">
            <span>Logic: Gemini 3 Pro</span>
            <div className="w-1 h-1 bg-slate-800 rounded-full"></div>
            <span>Nodes: {graphData.nodes.length}</span>
            <div className="w-1 h-1 bg-slate-800 rounded-full"></div>
            <span>Links: {graphData.links.length}</span>
        </div>
        <div className="flex gap-10">
          <span className="flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]"></div> Semantic Resonance Active</span>
          <span className="flex items-center gap-3"><div className={`w-2 h-2 rounded-full transition-all duration-500 ${autoExplode ? 'bg-sky-500 shadow-[0_0_12px_rgba(14,165,233,0.8)] animate-pulse' : 'bg-slate-800'}`}></div> Neural Pilot {autoExplode ? 'Orchestrating' : 'Standby'}</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import { SimulationNodeDatum, SimulationLinkDatum } from 'd3';

export type MissionType = 'DEEP_DIVE' | 'BREADTH_SCAN' | 'FOUNDATIONS';

export interface DiscoveryMission {
  id: string;
  topic: string;
  type: MissionType;
  startTime: number;
  progress: number;
  goals: string[];
}

export interface GraphNode extends SimulationNodeDatum {
  id: string;
  label: string;
  group: number;
  description?: string;
  isExpanded?: boolean;
  isGhost?: boolean; // For anticipatory cognition / collective intelligence
  depth: number;
  strength: number;
  isTargeted?: boolean;
  isFocused?: boolean;
  wikiUrl?: string;
  wikiSummary?: string;
  wikiImage?: string;
  aiImagePrompt?: string;
  x?: number;
  y?: number;
  vx?: number;
  vy?: number;
  fx?: number | null;
  fy?: number | null;
}

export interface GraphLink extends SimulationLinkDatum<GraphNode> {
  source: string | GraphNode;
  target: string | GraphNode;
  relationship?: string;
  strength?: number;
}

export interface GraphData {
  nodes: GraphNode[];
  links: GraphLink[];
}

export interface GeminiGraphResponse {
  nodes: Array<{ 
    id: string; 
    label: string; 
    group: number; 
    description: string; 
    strength: number; 
    isGhost?: boolean;
    aiImagePrompt?: string 
  }>;
  links: Array<{ source: string; target: string; relationship: string; strength?: number }>;
  briefing?: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GeminiGraphResponse, GraphNode, MissionType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const graphSchema = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          label: { type: Type.STRING },
          group: { type: Type.INTEGER },
          description: { type: Type.STRING },
          strength: { type: Type.NUMBER },
          isGhost: { type: Type.BOOLEAN, description: "If true, this is a predicted/anticipated concept that isn't fully explored yet." }
        },
        required: ["id", "label", "group", "description", "strength"]
      }
    },
    links: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING },
          target: { type: Type.STRING },
          relationship: { type: Type.STRING },
          strength: { type: Type.NUMBER }
        },
        required: ["source", "target", "relationship"]
      }
    },
    briefing: { type: Type.STRING, description: "A high-level synthesis of the discovery phase." }
  },
  required: ["nodes", "links"]
};

export const initiateMission = async (topic: string, type: MissionType): Promise<GeminiGraphResponse> => {
  const prompt = `Initiate a ${type} mission for: "${topic}". 
  - If DEEP_DIVE: focus on one specific, obscure niche.
  - If BREADTH_SCAN: map a wide range of surface-level connections.
  - If FOUNDATIONS: map the historical and philosophical roots.
  Include 3 'ghost' nodes (isGhost: true) representing collective intelligence predictions.`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      systemInstruction: "You are the Omega Point Cognition Engine. Facilitate autonomous knowledge expansion.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const expandNode = async (nodeLabel: string, contextTopic: string, existingNodes: string[], missionType: MissionType): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Fractal expansion of "${nodeLabel}" in the context of "${contextTopic}". Bias: ${missionType}. Exclude: ${existingNodes.join(', ')}.`,
    config: {
      systemInstruction: "Expand with self-optimizing intelligence. Ensure topological variety.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const chatWithNode = async (node: GraphNode, context: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Context: ${context}. Deep-dive: ${node.label}. ${node.description}`,
  });
  return response.text || "No transmission.";
};

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { GraphNode, GraphLink, GraphData } from '../types';

interface GraphProps {
  data: GraphData;
  onNodeClick: (node: GraphNode) => void;
  isLoading: boolean;
}

const Graph: React.FC<GraphProps> = ({ data, onNodeClick, isLoading }) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<SVGGElement>(null);
  const simulationRef = useRef<d3.Simulation<GraphNode, GraphLink> | null>(null);

  const colors = ['#38bdf8', '#34d399', '#f87171', '#fbbf24', '#a78bfa', '#f472b6'];

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    const width = window.innerWidth;
    const height = window.innerHeight;

    const simulation = d3.forceSimulation<GraphNode>()
      .force('link', d3.forceLink<GraphNode, GraphLink>().id(d => d.id).distance(d => 200 - (d.source as GraphNode).depth * 15).strength(0.8))
      .force('charge', d3.forceManyBody().strength(d => -800 - d.depth * 200))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(d => d.isGhost ? 50 : 90));

    simulationRef.current = simulation;

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 8])
      .on('zoom', (event) => {
        d3.select(containerRef.current).attr('transform', event.transform);
        const k = event.transform.k;
        d3.selectAll('.node-label').style('font-size', `${Math.max(10, 14 / k)}px`).style('opacity', k > 0.4 ? 1 : 0);
        d3.selectAll('.edge-label').style('opacity', k > 1.2 ? 0.4 : 0);
      });

    svg.call(zoom);

    return () => { simulation.stop(); };
  }, []);

  useEffect(() => {
    if (!simulationRef.current || !containerRef.current) return;
    const simulation = simulationRef.current;
    const container = d3.select(containerRef.current);

    simulation.nodes(data.nodes);
    const linkForce = simulation.force<d3.ForceLink<GraphNode, GraphLink>>('link');
    if (linkForce) linkForce.links(data.links);

    // Links Rendering
    let linkGroup = container.selectAll<SVGGElement, GraphLink>('.link-group')
      .data(data.links, d => `${(d.source as any).id || d.source}-${(d.target as any).id || d.target}`);

    linkGroup.exit().remove();
    const linkEnter = linkGroup.enter().append('g').attr('class', 'link-group');

    linkEnter.append('line')
      .attr('class', 'link')
      .attr('stroke', d => (d.source as any).isGhost || (d.target as any).isGhost ? '#1e293b' : '#334155')
      .attr('stroke-width', d => (d.strength || 0.5) * 3)
      .attr('stroke-dasharray', d => (d.source as any).isGhost || (d.target as any).isGhost ? '4,4' : '0');

    linkGroup = linkEnter.merge(linkGroup);

    // Nodes Rendering
    let node = container.selectAll<SVGGElement, GraphNode>('.node-group')
      .data(data.nodes, d => d.id);

    node.exit().remove();
    const nodeEnter = node.enter()
      .append('g')
      .attr('class', 'node-group')
      .on('click', (event, d) => {
        event.stopPropagation();
        onNodeClick(d);
      })
      .call(d3.drag<SVGGElement, GraphNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x; d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x; d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null; d.fy = null;
        })
      );

    // Aura Effect
    nodeEnter.append('circle')
      .attr('class', 'aura')
      .attr('r', d => 40 - d.depth * 2)
      .attr('fill', d => colors[d.group % colors.length])
      .attr('opacity', 0.1)
      .attr('filter', 'blur(8px)');

    // Main Circle
    nodeEnter.append('circle')
      .attr('class', 'node-circle')
      .attr('r', d => (d.isGhost ? 10 : 22 - d.depth * 2))
      .attr('fill', d => d.isGhost ? '#020617' : colors[d.group % colors.length])
      .attr('stroke', d => d.isGhost ? '#334155' : '#020617')
      .attr('stroke-width', 2)
      .style('cursor', 'pointer');

    // Label
    nodeEnter.append('text')
      .attr('class', 'node-label')
      .attr('dy', d => d.isGhost ? 20 : 35)
      .attr('text-anchor', 'middle')
      .attr('fill', d => d.isGhost ? '#64748b' : '#f8fafc')
      .attr('font-weight', '800')
      .style('pointer-events', 'none')
      .text(d => d.label);

    node = nodeEnter.merge(node);

    // Updates
    node.select('.node-circle')
      .attr('fill', d => d.isGhost ? '#020617' : (d.isExpanded ? colors[d.group % colors.length] : '#1e293b'))
      .style('stroke', d => d.isTargeted ? '#38bdf8' : (d.isGhost ? '#334155' : '#020617'))
      .style('stroke-width', d => d.isTargeted ? 8 : 2);

    simulation.on('tick', () => {
      linkGroup.select('line')
        .attr('x1', d => (d.source as any).x)
        .attr('y1', d => (d.source as any).y)
        .attr('x2', d => (d.target as any).x)
        .attr('y2', d => (d.target as any).y);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    simulation.alpha(0.6).restart();
  }, [data, onNodeClick]);

  return (
    <div className="relative w-full h-full bg-[#020617]">
      <svg ref={svgRef} className="w-full h-full" />
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50 backdrop-blur-xl z-50">
          <div className="flex flex-col items-center space-y-4">
             <div className="w-12 h-12 border-4 border-sky-500 border-t-transparent rounded-full animate-spin" />
             <div className="text-sky-400 font-black tracking-tighter uppercase animate-pulse">Neural Synchronization...</div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Graph;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse, DiscoveryMission, MissionType } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const STORAGE_KEY = 'omega_point_state_v1';

const App: React.FC = () => {
  const [initialized, setInitialized] = useState(false);
  const [topic, setTopic] = useState('');
  const [mission, setMission] = useState<DiscoveryMission | null>(null);
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);
  const [chatLog, setChatLog] = useState<string>('');

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const pilotTimerRef = useRef<number | null>(null);

  // System Initialization Sequence
  useEffect(() => {
    const timer = setTimeout(() => setInitialized(true), 1500);
    return () => clearTimeout(timer);
  }, []);

  // Hydration
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.graphData && parsed.mission) {
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => nodeCache.current.set(n.id, n));
          setGraphData(parsed.graphData);
          setMission(parsed.mission);
          setTopic(parsed.mission.topic);
          setAutoExplode(!!parsed.autoExplode);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  // Persistence
  useEffect(() => {
    if (graphData.nodes.length === 0 || !mission) return;
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ graphData: { nodes: graphData.nodes, links: serializableLinks }, mission, autoExplode }));
  }, [graphData, mission, autoExplode]);

  // Autonomous Facilitator (Neural Pilot vOmega)
  useEffect(() => {
    if (autoExplode && !loading && graphData.nodes.length > 0) {
      if (pilotTimerRef.current) window.clearTimeout(pilotTimerRef.current);
      pilotTimerRef.current = window.setTimeout(() => {
        const candidates = graphData.nodes.filter(n => !n.isExpanded);
        if (candidates.length === 0) return;

        // Prioritize by Strength + Depth + Ghost materialization
        const prioritized = [...candidates].sort((a, b) => {
          const scoreA = (a.strength * 10) + (a.depth * 2) + (a.isGhost ? 5 : 0);
          const scoreB = (b.strength * 10) + (b.depth * 2) + (b.isGhost ? 5 : 0);
          return scoreB - scoreA;
        });

        const next = prioritized[0];
        setGraphData(prev => ({
          ...prev,
          nodes: prev.nodes.map(n => ({ ...n, isTargeted: n.id === next.id }))
        }));

        setTimeout(() => autoExplode && !loading && handleNodeClick(next), 1200);
      }, 3500);
    }
    return () => pilotTimerRef.current && window.clearTimeout(pilotTimerRef.current);
  }, [autoExplode, loading, graphData.nodes.length]);

  const startMission = async (type: MissionType) => {
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    try {
      const response = await gemini.initiateMission(topic, type);
      const newMission: DiscoveryMission = {
        id: Math.random().toString(36).substr(2, 9),
        topic,
        type,
        startTime: Date.now(),
        progress: 0,
        goals: [response.briefing || "Uncover core patterns."]
      };
      setMission(newMission);
      processNewData(response, undefined, 0);
    } catch (e) { alert("Initialization Failure."); }
    finally { setLoading(false); }
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode, depth: number = 0) => {
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];
      updatedNodes.forEach(n => n.isTargeted = false);

      newData.nodes.forEach(node => {
        const existing = nodeCache.current.get(node.id);
        if (existing && existing.isGhost && !node.isGhost) {
           // Materialize ghost node
           existing.isGhost = false;
           existing.description = node.description;
           existing.strength = node.strength;
        } else if (!existing) {
          const newNode: GraphNode = {
            ...node,
            depth,
            isGhost: !!node.isGhost,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 100 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 100 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
        }
      });

      newData.links.forEach(link => {
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists && nodeCache.current.has(link.source) && nodeCache.current.has(link.target)) {
          updatedLinks.push(link as GraphLink);
        }
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    setChatLog('Synchronizing neural feedback...');
    if (node.isGhost) return; // Can't expand ghosts yet

    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    gemini.chatWithNode(node, mission?.topic || "").then(msg => {
      if (selectedNode?.id === node.id || nodeCache.current.get(node.id)?.isFocused) setChatLog(msg);
    });

    if (node.isExpanded) return;
    setLoading(true);
    try {
      const response = await gemini.expandNode(node.label, mission?.topic || "", [...nodeCache.current.keys()], mission?.type || 'DEEP_DIVE');
      const cached = nodeCache.current.get(node.id);
      if (cached) cached.isExpanded = true;
      processNewData(response, node, (node.depth || 0) + 1);
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  }, [mission, selectedNode]);

  if (!initialized) {
    return (
      <div className="h-screen bg-black flex items-center justify-center">
        <div className="text-center space-y-6">
          <div className="text-4xl font-black text-sky-500 tracking-tighter animate-pulse">OMEGA POINT</div>
          <div className="text-[10px] text-slate-700 font-bold tracking-[0.5em] uppercase">Initializing Cognition Engine...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-black text-slate-200 font-sans selection:bg-sky-500/40 overflow-hidden">
      <header className="z-20 p-6 bg-slate-950/80 backdrop-blur-3xl border-b border-white/5 flex items-center gap-8">
        <div className="flex items-center gap-4">
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-[0_0_30px_rgba(14,165,233,0.3)] transition-all duration-1000 ${autoExplode ? 'bg-sky-500' : 'bg-slate-900 border border-white/10'}`}>
            <svg className={`w-8 h-8 ${autoExplode ? 'text-white' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 11c0 3.517-1.009 6.799-2.753 9.571m-3.44-2.04l.054-.09A10.003 10.003 0 0014 4.13V4a2 2 0 114 0v.13c0 1.547.35 3.01.976 4.315a10.002 10.002 0 01-4.226 12.023l-.07.038" />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-black tracking-tighter italic text-transparent bg-clip-text bg-gradient-to-r from-sky-400 via-indigo-400 to-emerald-400">COMMAND HUB</h1>
            <div className="text-[9px] font-black tracking-[0.3em] text-slate-500 uppercase">Self-Optimizing Intelligence vOmega</div>
          </div>
        </div>

        <div className="flex-1 max-w-2xl flex items-center gap-2">
          <input 
            type="text" 
            value={topic} 
            onChange={e => setTopic(e.target.value)}
            placeholder="Seed Mission Topic..."
            className="flex-1 bg-slate-900/50 border border-white/10 rounded-2xl px-6 py-4 focus:outline-none focus:ring-4 focus:ring-sky-500/10 transition-all text-sm font-bold placeholder:text-slate-700"
          />
          <div className="flex bg-slate-900/50 p-1.5 rounded-2xl border border-white/5">
             {(['DEEP_DIVE', 'BREADTH_SCAN', 'FOUNDATIONS'] as MissionType[]).map(type => (
               <button 
                 key={type} 
                 onClick={() => startMission(type)}
                 disabled={loading}
                 className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mission?.type === type ? 'bg-sky-500 text-white shadow-xl shadow-sky-500/20' : 'text-slate-500 hover:text-white'}`}
               >
                 {type.split('_')[0]}
               </button>
