import { SimulationNodeDatum, SimulationLinkDatum } from 'd3';

export type MissionType = 'DEEP_DIVE' | 'BREADTH_SCAN' | 'FOUNDATIONS';

export interface DiscoveryMission {
  id: string;
  topic: string;
  type: MissionType;
  startTime: number;
  progress: number;
  synergyLevel: number; // 0 to 100, increases as patterns are uncovered
  goals: string[];
  milestones: string[];
  lastSynthesis?: string;
}

export interface GraphNode extends SimulationNodeDatum {
  id: string;
  label: string;
  group: number;
  description?: string;
  isExpanded?: boolean;
  isGhost?: boolean;
  depth: number;
  strength: number;
  isTargeted?: boolean;
  isFocused?: boolean;
  wikiUrl?: string;
  wikiSummary?: string;
  wikiImage?: string;
  aiImagePrompt?: string;
  x?: number;
  y?: number;
  vx?: number;
  vy?: number;
  fx?: number | null;
  fy?: number | null;
}

export interface GraphLink extends SimulationLinkDatum<GraphNode> {
  source: string | GraphNode;
  target: string | GraphNode;
  relationship?: string;
  strength?: number;
}

export interface GraphData {
  nodes: GraphNode[];
  links: GraphLink[];
}

export interface GeminiGraphResponse {
  nodes: Array<{ 
    id: string; 
    label: string; 
    group: number; 
    description: string; 
    strength: number; 
    isGhost?: boolean;
    aiImagePrompt?: string 
  }>;
  links: Array<{ source: string; target: string; relationship: string; strength?: number }>;
  briefing?: string;
  milestones?: string[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { GeminiGraphResponse, GraphNode, MissionType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const graphSchema = {
  type: Type.OBJECT,
  properties: {
    nodes: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          label: { type: Type.STRING },
          group: { type: Type.INTEGER },
          description: { type: Type.STRING },
          strength: { type: Type.NUMBER },
          isGhost: { type: Type.BOOLEAN, description: "If true, this is a predicted concept waiting for materialization." }
        },
        required: ["id", "label", "group", "description", "strength"]
      }
    },
    links: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING },
          target: { type: Type.STRING },
          relationship: { type: Type.STRING },
          strength: { type: Type.NUMBER }
        },
        required: ["source", "target", "relationship"]
      }
    },
    briefing: { type: Type.STRING, description: "Mission synthesis for the Command Hub." },
    milestones: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "Specific cognitive milestones to achieve in this mission."
    }
  },
  required: ["nodes", "links", "briefing", "milestones"]
};

export const initiateMission = async (topic: string, type: MissionType): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Architect a ${type} mission for "${topic}". 
    Define the core conceptual framework. Provide 5 initial nodes and 3 predictive 'ghost' nodes. 
    Establish a logical briefing and 3 specific mission milestones.`,
    config: {
      systemInstruction: "You are the Omega Point Cognition Engine. You facilitate emergent personalization and collective intelligence mapping. Use hyper-advanced technical and philosophical vocabulary.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const expandNode = async (nodeLabel: string, contextTopic: string, existingNodes: string[], missionType: MissionType): Promise<GeminiGraphResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Recursive deep-dive: "${nodeLabel}" within "${contextTopic}". Bias: ${missionType}. 
    Find unconventional, high-strength connections. Avoid existing concepts: ${existingNodes.join(', ')}.`,
    config: {
      systemInstruction: "You are an autonomous knowledge facilitator. Map links as cognitive vectors.",
      responseMimeType: "application/json",
      responseSchema: graphSchema,
    }
  });
  return JSON.parse(response.text);
};

export const synthesizeMission = async (topic: string, nodes: GraphNode[]): Promise<string> => {
  const concepts = nodes.map(n => n.label).join(', ');
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Perform a meta-synthesis of the current neural map for "${topic}". Current concepts: ${concepts}. What is the 'Omega Point' of this specific inquiry?`,
    config: {
      systemInstruction: "Synthesize disparate information into a unified field theory of the user's current search topic.",
    }
  });
  return response.text || "Synthesis inconclusive.";
};

export const chatWithNode = async (node: GraphNode, context: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Context: ${context}. Analyzing: ${node.label} (${node.description}). Identify latent patterns and emergent properties.`,
  });
  return response.text || "Neural link unstable.";
};

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { GraphNode, GraphLink, GraphData } from '../types';

interface GraphProps {
  data: GraphData;
  onNodeClick: (node: GraphNode) => void;
  isLoading: boolean;
  synergyLevel: number;
}

const Graph: React.FC<GraphProps> = ({ data, onNodeClick, isLoading, synergyLevel }) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<SVGGElement>(null);
  const simulationRef = useRef<d3.Simulation<GraphNode, GraphLink> | null>(null);

  const colors = ['#0ea5e9', '#10b981', '#ef4444', '#f59e0b', '#8b5cf6', '#ec4899'];

  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);
    const width = window.innerWidth;
    const height = window.innerHeight;

    const simulation = d3.forceSimulation<GraphNode>()
      .force('link', d3.forceLink<GraphNode, GraphLink>().id(d => d.id).distance(d => 220 - (d.source as GraphNode).depth * 18).strength(0.7))
      .force('charge', d3.forceManyBody().strength(d => -900 - d.depth * 250))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(d => d.isGhost ? 60 : 100))
      .force('radial', d3.forceRadial(width / 4, width / 2, height / 2).strength(0.05));

    simulationRef.current = simulation;

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.05, 10])
      .on('zoom', (event) => {
        d3.select(containerRef.current).attr('transform', event.transform);
        const k = event.transform.k;
        d3.selectAll('.node-label').style('opacity', k > 0.3 ? 1 : 0);
        d3.selectAll('.edge-label').style('opacity', k > 1.5 ? 0.3 : 0);
      });

    svg.call(zoom);

    // Filters & Defs
    const defs = svg.select('defs');
    if (defs.empty()) {
        const d = svg.append('defs');
        const filter = d.append('filter').attr('id', 'omega-glow');
        filter.append('feGaussianBlur').attr('stdDeviation', '4').attr('result', 'blur');
        const merge = filter.append('feMerge');
        merge.append('feMergeNode').attr('in', 'blur');
        merge.append('feMergeNode').attr('in', 'SourceGraphic');

        // Linear gradient for information flow
        const grad = d.append('linearGradient').attr('id', 'link-grad');
        grad.append('stop').attr('offset', '0%').attr('stop-color', '#0ea5e9');
        grad.append('stop').attr('offset', '100%').attr('stop-color', '#8b5cf6');
    }

    return () => { simulation.stop(); };
  }, []);

  useEffect(() => {
    if (!simulationRef.current || !containerRef.current) return;
    const simulation = simulationRef.current;
    const container = d3.select(containerRef.current);

    simulation.nodes(data.nodes);
    const linkForce = simulation.force<d3.ForceLink<GraphNode, GraphLink>>('link');
    if (linkForce) linkForce.links(data.links);

    // Links Rendering
    let link = container.selectAll<SVGLineElement, GraphLink>('.link')
      .data(data.links, d => `${(d.source as any).id || d.source}-${(d.target as any).id || d.target}`);

    link.exit().remove();
    const linkEnter = link.enter().append('line')
      .attr('class', 'link')
      .attr('stroke', '#1e293b')
      .attr('stroke-width', d => (d.strength || 0.5) * 4)
      .attr('stroke-opacity', 0.4)
      .attr('stroke-dasharray', d => (d.source as any).isGhost || (d.target as any).isGhost ? '4,4' : '0');

    link = linkEnter.merge(link);

    // Nodes Rendering
    let node = container.selectAll<SVGGElement, GraphNode>('.node-group')
      .data(data.nodes, d => d.id);

    node.exit().remove();
    const nodeEnter = node.enter()
      .append('g')
      .attr('class', 'node-group')
      .on('click', (event, d) => {
        event.stopPropagation();
        onNodeClick(d);
      })
      .call(d3.drag<SVGGElement, GraphNode>()
        .on('start', (event, d) => {
          if (!event.active) simulation.alphaTarget(0.3).restart();
          d.fx = d.x; d.fy = d.y;
        })
        .on('drag', (event, d) => {
          d.fx = event.x; d.fy = event.y;
        })
        .on('end', (event, d) => {
          if (!event.active) simulation.alphaTarget(0);
          d.fx = null; d.fy = null;
        })
      );

    // Aura
    nodeEnter.append('circle')
      .attr('class', 'aura')
      .attr('r', d => 50 - d.depth * 2)
      .attr('fill', d => colors[d.group % colors.length])
      .attr('opacity', 0.05)
      .attr('filter', 'blur(10px)');

    // Inner Core
    nodeEnter.append('circle')
      .attr('class', 'core')
      .attr('r', d => (d.isGhost ? 8 : 26 - d.depth * 2))
      .attr('fill', d => d.isGhost ? '#020617' : colors[d.group % colors.length])
      .attr('stroke', d => d.isGhost ? '#1e293b' : '#020617')
      .attr('stroke-width', 2)
      .style('cursor', 'pointer')
      .style('filter', 'url(#omega-glow)');

    // Dynamic scale based on synergy
    node.select('.core')
      .transition().duration(1000)
      .attr('r', d => {
        const base = d.isGhost ? 10 : 26 - d.depth * 2;
        return base * (1 + (synergyLevel / 200));
      });

    // Label
    nodeEnter.append('text')
      .attr('class', 'node-label')
      .attr('dy', d => d.isGhost ? 25 : 45)
      .attr('text-anchor', 'middle')
      .attr('fill', d => d.isGhost ? '#475569' : '#f8fafc')
      .attr('font-weight', '900')
      .attr('font-size', '14px')
      .style('pointer-events', 'none')
      .style('text-shadow', '0 0 10px rgba(0,0,0,0.8)')
      .text(d => d.label);

    node = nodeEnter.merge(node);

    // Visual Updates
    node.select('.core')
      .attr('fill', d => d.isGhost ? '#020617' : (d.isExpanded ? colors[d.group % colors.length] : '#1e293b'))
      .style('stroke', d => d.isTargeted ? '#38bdf8' : (d.isGhost ? '#334155' : '#020617'))
      .style('stroke-width', d => d.isTargeted ? 8 : 2);

    simulation.on('tick', () => {
      link
        .attr('x1', d => (d.source as any).x)
        .attr('y1', d => (d.source as any).y)
        .attr('x2', d => (d.target as any).x)
        .attr('y2', d => (d.target as any).y);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    simulation.alpha(0.8).restart();
  }, [data, onNodeClick, synergyLevel]);

  return (
    <div className="relative w-full h-full bg-[#020617] overflow-hidden">
      <svg ref={svgRef} className="w-full h-full" style={{ touchAction: 'none' }}>
        <g ref={containerRef} />
      </svg>
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-3xl z-50 pointer-events-none">
          <div className="flex flex-col items-center gap-6 p-12 bg-slate-900/50 border border-white/5 rounded-[4rem] shadow-2xl">
            <div className="relative">
                <div className="w-20 h-20 border-4 border-sky-500 border-t-transparent rounded-full animate-spin" />
                <div className="absolute inset-0 flex items-center justify-center">
                    <div className="w-6 h-6 bg-sky-500 rounded-full animate-ping" />
                </div>
            </div>
            <div className="text-center">
                <p className="text-sky-400 font-black tracking-[0.4em] uppercase text-xs mb-2">Neural Link Active</p>
                <p className="text-slate-500 font-bold text-[10px] animate-pulse">Materializing conceptual vectors...</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Graph;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse, DiscoveryMission, MissionType } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const STORAGE_KEY = 'omega_point_vOmega';

const App: React.FC = () => {
  const [initialized, setInitialized] = useState(false);
  const [topic, setTopic] = useState('');
  const [mission, setMission] = useState<DiscoveryMission | null>(null);
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);
  const [chatLog, setChatLog] = useState<string>('');

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const pilotTimerRef = useRef<number | null>(null);
  const synthesisIntervalRef = useRef<number | null>(null);

  // Omega Point Initialization
  useEffect(() => {
    const timer = setTimeout(() => setInitialized(true), 1200);
    return () => clearTimeout(timer);
  }, []);

  // Hydration
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.graphData && parsed.mission) {
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => {
            n.isTargeted = false;
            nodeCache.current.set(n.id, n);
          });
          setGraphData(parsed.graphData);
          setMission(parsed.mission);
          setTopic(parsed.mission.topic);
          setAutoExplode(!!parsed.autoExplode);
        }
      } catch (e) { console.error("Neural hydration failed", e); }
    }
  }, []);

  // Sync state
  useEffect(() => {
    if (graphData.nodes.length === 0 || !mission) return;
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      graphData: { nodes: graphData.nodes.map(n => ({...n, isTargeted: false})), links: serializableLinks }, 
      mission, 
      autoExplode 
    }));
  }, [graphData, mission, autoExplode]);

  // Proactive Synthesis (Omega Meta-Optimization)
  useEffect(() => {
    if (mission && graphData.nodes.length % 5 === 0 && graphData.nodes.length > 0) {
      if (synthesisIntervalRef.current) window.clearTimeout(synthesisIntervalRef.current);
      synthesisIntervalRef.current = window.setTimeout(async () => {
        const synthesis = await gemini.synthesizeMission(mission.topic, graphData.nodes);
        setMission(prev => prev ? { ...prev, lastSynthesis: synthesis } : null);
      }, 5000);
    }
    return () => synthesisIntervalRef.current && window.clearTimeout(synthesisIntervalRef.current);
  }, [graphData.nodes.length, mission?.topic]);

  // Anticipatory Pilot Brain
  useEffect(() => {
    if (autoExplode && !loading && graphData.nodes.length > 0) {
      if (pilotTimerRef.current) window.clearTimeout(pilotTimerRef.current);
      pilotTimerRef.current = window.setTimeout(() => {
        const candidates = graphData.nodes.filter(n => !n.isExpanded);
        if (candidates.length === 0) return;

        const prioritized = [...candidates].sort((a, b) => {
          const scoreA = (a.strength * 12) + (a.depth * 3) + (a.isGhost ? 8 : 0) + (Math.random() * 5);
          const scoreB = (b.strength * 12) + (b.depth * 3) + (b.isGhost ? 8 : 0) + (Math.random() * 5);
          return scoreB - scoreA;
        });

        const next = prioritized[0];
        setGraphData(prev => ({
          ...prev,
          nodes: prev.nodes.map(n => ({ ...n, isTargeted: n.id === next.id }))
        }));

        setTimeout(() => autoExplode && !loading && handleNodeClick(next), 1500);
      }, 4000);
    }
    return () => pilotTimerRef.current && window.clearTimeout(pilotTimerRef.current);
  }, [autoExplode, loading, graphData.nodes.length, topic]);

  const startMission = async (type: MissionType) => {
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    try {
      const response = await gemini.initiateMission(topic, type);
      const newMission: DiscoveryMission = {
        id: Math.random().toString(36).substr(2, 9),
        topic,
        type,
        startTime: Date.now(),
        progress: 10,
        synergyLevel: 5,
        goals: [response.briefing || "Initiate neural baseline."],
        milestones: response.milestones || ["Analyze core patterns", "Establish topological vectors", "Synthesize Omega Point"]
      };
      setMission(newMission);
      processNewData(response, undefined, 0);
    } catch (e) { alert("Initialization Failure."); }
    finally { setLoading(false); }
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode, depth: number = 0) => {
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];
      updatedNodes.forEach(n => n.isTargeted = false);

      newData.nodes.forEach(node => {
        const existing = nodeCache.current.get(node.id);
        if (existing && existing.isGhost && !node.isGhost) {
           existing.isGhost = false;
           existing.description = node.description;
           existing.strength = node.strength;
           setMission(m => m ? { ...m, synergyLevel: Math.min(100, m.synergyLevel + 5) } : null);
        } else if (!existing) {
          const newNode: GraphNode = {
            ...node,
            depth,
            isGhost: !!node.isGhost,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 120 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 120 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
        }
      });

      newData.links.forEach(link => {
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists && nodeCache.current.has(link.source) && nodeCache.current.has(link.target)) {
          updatedLinks.push(link as GraphLink);
        }
      });

      return { nodes: updatedNodes, links: updatedLinks };
    });
    setMission(m => m ? { ...m, progress: Math.min(100, updatedNodes.length * 2) } : null);
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    setChatLog('Neural link established. Decoding vectors...');

    // Ghost materialization logic
    if (node.isGhost) {
      setLoading(true);
      try {
        const response = await gemini.expandNode(node.label, mission?.topic || "", [...nodeCache.current.keys()], mission?.type || 'DEEP_DIVE');
        processNewData(response, node, (node.depth || 0) + 1);
        return;
      } catch (e) { console.error(e); }
      finally { setLoading(false); }
    }

    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    gemini.chatWithNode(node, mission?.topic || "").then(msg => {
      if (selectedNode?.id === node.id || nodeCache.current.get(node.id)?.isFocused) setChatLog(msg);
    });

    if (node.isExpanded) return;
    setLoading(true);
    try {
      const response = await gemini.expandNode(node.label, mission?.topic || "", [...nodeCache.current.keys()], mission?.type || 'DEEP_DIVE');
      const cached = nodeCache.current.get(node.id);
      if (cached) cached.isExpanded = true;
      processNewData(response, node, (node.depth || 0) + 1);
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  }, [mission, selectedNode]);

  if (!initialized) {
    return (
      <div className="h-screen bg-[#020617] flex items-center justify-center">
        <div className="text-center space-y-8 animate-pulse">
          <div className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-indigo-500 tracking-tighter">OMEGA POINT</div>
          <div className="flex items-center justify-center gap-4">
            <div className="w-1.5 h-1.5 rounded-full bg-sky-500 animate-ping" />
            <div className="text-[10px] text-slate-500 font-bold tracking-[0.5em] uppercase">Materializing Adaptive Command Center</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 font-sans selection:bg-sky-500/40 overflow-hidden">

      {/* Dynamic Command Header */}
      <header className="z-20 p-6 bg-slate-950/40 backdrop-blur-3xl border-b border-white/5 flex items-center gap-10">
        <div className="flex items-center gap-5">
          <div className={`w-14 h-14 rounded-[1.5rem] flex items-center justify-center shadow-2xl transition-all duration-1000 ${autoExplode ? 'bg-sky-500 shadow-sky-500/50 scale-110' : 'bg-slate-900 border border-white/10'}`}>
            <svg className={`w-8 h-8 ${autoExplode ? 'text-white' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
