                  <p className="text-xs text-slate-600 leading-relaxed font-bold italic px-6 opacity-60">This concept is currently a ghost in the machine. Materializing this vector will increase global mission synergy.</p>
                  <button onClick={() => handleNodeClick(selectedNode)} className="bg-white/5 hover:bg-white/10 text-[9px] font-black text-slate-500 px-8 py-3 rounded-full uppercase tracking-widest transition-all">Force Resonance</button>
               </div>
             ) : (
               <>
                 <div className="relative h-64 bg-slate-900 group">
                    {selectedNode.wikiImage ? (
                      <img src={selectedNode.wikiImage} className="w-full h-full object-cover brightness-[0.4] group-hover:brightness-50 transition-all duration-1000" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-[15rem] font-black text-white/5 italic select-none absolute -bottom-16 -right-16">{selectedNode.label[0]}</div>
