                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent" />
                    <button onClick={() => setSelectedNode(null)} className="absolute top-8 right-8 p-3 bg-black/60 hover:bg-black rounded-full transition-all text-white/40 hover:text-white border border-white/5">
                       <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 18L18 6M6 6l12 12" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/></svg>
