                          <span className="text-[10px] font-black border border-white/10 text-slate-500 px-3 py-1 rounded-lg uppercase tracking-widest">Weight {selectedNode.strength?.toFixed(3)}</span>
                       </div>
                       <h3 className="text-4xl font-black tracking-tighter text-white italic">{selectedNode.label}</h3>
                    </div>

                    <div className="space-y-8">
                       <div className="relative">
                          <div className="absolute -left-8 top-0 bottom-0 w-1 bg-gradient-to-b from-sky-500 to-indigo-500 rounded-full opacity-50" />
