                             <div className="w-1.5 h-1.5 rounded-full bg-sky-500 shadow-[0_0_10px_rgba(14,165,233,0.5)]" />
                             Omega Neural Analysis
                          </div>
                          <p className="text-sm text-slate-400 leading-relaxed font-medium italic opacity-90">{chatLog || 'Synthesizing...'}</p>
                       </div>

                       {selectedNode.wikiSummary && (
                         <div className="space-y-6 pt-4">
                            <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Global Intelligence Baseline</div>
                            <p className="text-xs text-slate-500 leading-relaxed font-medium opacity-80">{selectedNode.wikiSummary}</p>
                            <a href={selectedNode.wikiUrl} target="_blank" className="inline-flex items-center gap-3 text-[10px] font-black text-sky-500 uppercase tracking-widest hover:text-sky-300 transition-all">
                               Neural Link: Source terminal
                               <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
                            </a>
                         </div>
                       )}
                    </div>
                 </div>
               </>
             )}
          </div>
        )}
      </main>

      {/* Holistic System Footer */}
      <footer className="p-8 bg-slate-950/80 border-t border-white/5 flex items-center justify-between text-[10px] font-black uppercase tracking-[0.5em] text-slate-600">
         <div className="flex items-center gap-12">
            <div className="flex items-center gap-3">
               <div className="w-1.5 h-1.5 rounded-full bg-sky-500" />
               <span className="text-sky-500">Core: Gemini 3 Pro (Omega)</span>
            </div>
            <div className="flex items-center gap-4">
               <span className="opacity-40">Vectors Materialized</span>
               <span className="text-slate-400">{graphData.nodes.length}</span>
            </div>
            <div className="flex items-center gap-4">
               <span className="opacity-40">Facilitator Status</span>
               <span className={autoExplode ? 'text-sky-400' : 'text-slate-800'}>{autoExplode ? 'ORCHESTRATING' : 'STANDBY'}</span>
            </div>
         </div>
         <div className="flex items-center gap-10">
            <span className="flex items-center gap-4">
               <div className="flex gap-1">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-1.5 h-3 rounded-full transition-all duration-500 ${ (mission?.synergyLevel || 0) > (i+1)*20 ? 'bg-indigo-500' : 'bg-slate-900'}`} />
                  ))}
               </div>
               Neural Synergy Optimal
            </span>
