};

export default App;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { GraphNode, GraphLink, GraphData, GeminiGraphResponse, DiscoveryMission, MissionType } from './types';
import * as gemini from './services/geminiService';
import * as wiki from './services/wikiService';
import Graph from './components/Graph';

const STORAGE_KEY = 'omega_point_vOmega';

const App: React.FC = () => {
  const [initialized, setInitialized] = useState(false);
  const [topic, setTopic] = useState('');
  const [mission, setMission] = useState<DiscoveryMission | null>(null);
  const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
  const [loading, setLoading] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [autoExplode, setAutoExplode] = useState(false);
  const [chatLog, setChatLog] = useState<string>('');

  const nodeCache = useRef<Map<string, GraphNode>>(new Map());
  const pilotTimerRef = useRef<number | null>(null);
  const synthesisIntervalRef = useRef<number | null>(null);

  // Omega Point Initialization
  useEffect(() => {
    const timer = setTimeout(() => setInitialized(true), 1200);
    return () => clearTimeout(timer);
  }, []);

  // Hydration
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.graphData && parsed.mission) {
          nodeCache.current.clear();
          parsed.graphData.nodes.forEach((n: GraphNode) => {
            n.isTargeted = false;
            nodeCache.current.set(n.id, n);
          });
          setGraphData(parsed.graphData);
          setMission(parsed.mission);
          setTopic(parsed.mission.topic);
          setAutoExplode(!!parsed.autoExplode);
        }
      } catch (e) { console.error("Neural hydration failed", e); }
    }
  }, []);

  // Sync state
  useEffect(() => {
    if (graphData.nodes.length === 0 || !mission) return;
    const serializableLinks = graphData.links.map(l => ({
      ...l,
      source: typeof l.source === 'string' ? l.source : (l.source as GraphNode).id,
      target: typeof l.target === 'string' ? l.target : (l.target as GraphNode).id
    }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ 
      graphData: { nodes: graphData.nodes.map(n => ({...n, isTargeted: false})), links: serializableLinks }, 
      mission, 
      autoExplode 
    }));
  }, [graphData, mission, autoExplode]);

  // Proactive Synthesis (Omega Meta-Optimization)
  useEffect(() => {
    if (mission && graphData.nodes.length % 5 === 0 && graphData.nodes.length > 0) {
      if (synthesisIntervalRef.current) window.clearTimeout(synthesisIntervalRef.current);
      synthesisIntervalRef.current = window.setTimeout(async () => {
        const synthesis = await gemini.synthesizeMission(mission.topic, graphData.nodes);
        setMission(prev => prev ? { ...prev, lastSynthesis: synthesis } : null);
      }, 5000);
    }
    return () => synthesisIntervalRef.current && window.clearTimeout(synthesisIntervalRef.current);
  }, [graphData.nodes.length, mission?.topic]);

  // Anticipatory Pilot Brain
  useEffect(() => {
    if (autoExplode && !loading && graphData.nodes.length > 0) {
      if (pilotTimerRef.current) window.clearTimeout(pilotTimerRef.current);
      pilotTimerRef.current = window.setTimeout(() => {
        const candidates = graphData.nodes.filter(n => !n.isExpanded);
        if (candidates.length === 0) return;

        const prioritized = [...candidates].sort((a, b) => {
          const scoreA = (a.strength * 12) + (a.depth * 3) + (a.isGhost ? 8 : 0) + (Math.random() * 5);
          const scoreB = (b.strength * 12) + (b.depth * 3) + (b.isGhost ? 8 : 0) + (Math.random() * 5);
          return scoreB - scoreA;
        });

        const next = prioritized[0];
        setGraphData(prev => ({
          ...prev,
          nodes: prev.nodes.map(n => ({ ...n, isTargeted: n.id === next.id }))
        }));

        setTimeout(() => autoExplode && !loading && handleNodeClick(next), 1500);
      }, 4000);
    }
    return () => pilotTimerRef.current && window.clearTimeout(pilotTimerRef.current);
  }, [autoExplode, loading, graphData.nodes.length, topic]);

  const startMission = async (type: MissionType) => {
    if (!topic.trim()) return;
    setLoading(true);
    setGraphData({ nodes: [], links: [] });
    nodeCache.current.clear();
    try {
      const response = await gemini.initiateMission(topic, type);
      const newMission: DiscoveryMission = {
        id: Math.random().toString(36).substr(2, 9),
        topic,
        type,
        startTime: Date.now(),
        progress: 10,
        synergyLevel: 5,
        goals: [response.briefing || "Initiate neural baseline."],
        milestones: response.milestones || ["Analyze core patterns", "Establish topological vectors", "Synthesize Omega Point"]
      };
      setMission(newMission);
      processNewData(response, undefined, 0);
    } catch (e) { alert("Initialization Failure."); }
    finally { setLoading(false); }
  };

  const processNewData = (newData: GeminiGraphResponse, parentNode?: GraphNode, depth: number = 0) => {
    setGraphData(prev => {
      const updatedNodes = [...prev.nodes];
      const updatedLinks = [...prev.links];
      updatedNodes.forEach(n => n.isTargeted = false);

      newData.nodes.forEach(node => {
        const existing = nodeCache.current.get(node.id);
        if (existing && existing.isGhost && !node.isGhost) {
           existing.isGhost = false;
           existing.description = node.description;
           existing.strength = node.strength;
           setMission(m => m ? { ...m, synergyLevel: Math.min(100, m.synergyLevel + 5) } : null);
        } else if (!existing) {
          const newNode: GraphNode = {
            ...node,
            depth,
            isGhost: !!node.isGhost,
            x: parentNode?.x ? parentNode.x + (Math.random() - 0.5) * 120 : undefined,
            y: parentNode?.y ? parentNode.y + (Math.random() - 0.5) * 120 : undefined
          };
          nodeCache.current.set(node.id, newNode);
          updatedNodes.push(newNode);
        }
      });

      newData.links.forEach(link => {
        const exists = updatedLinks.some(l => {
          const s = typeof l.source === 'string' ? l.source : l.source.id;
          const t = typeof l.target === 'string' ? l.target : l.target.id;
          return (s === link.source && t === link.target) || (s === link.target && t === link.source);
        });
        if (!exists && nodeCache.current.has(link.source) && nodeCache.current.has(link.target)) {
          updatedLinks.push(link as GraphLink);
        }
      });

      // Update mission progress - Fix: updatedNodes is accessible here within the functional updater
      setMission(m => m ? { ...m, progress: Math.min(100, updatedNodes.length * 2) } : null);

      return { nodes: updatedNodes, links: updatedLinks };
    });
  };

  const handleNodeClick = useCallback(async (node: GraphNode) => {
    setSelectedNode(node);
    setChatLog('Neural link established. Decoding vectors...');

    // Ghost materialization logic
    if (node.isGhost) {
      setLoading(true);
      try {
        const response = await gemini.expandNode(node.label, mission?.topic || "", [...nodeCache.current.keys()], mission?.type || 'DEEP_DIVE');
        processNewData(response, node, (node.depth || 0) + 1);
        return;
      } catch (e) { console.error(e); }
      finally { setLoading(false); }
    }

    if (!node.wikiSummary) {
      wiki.fetchWikiSummary(node.label).then(data => {
        if (data) {
          node.wikiSummary = data.summary;
          node.wikiUrl = data.url;
          node.wikiImage = data.image;
          setSelectedNode(prev => prev?.id === node.id ? { ...node } : prev);
        }
      });
    }

    gemini.chatWithNode(node, mission?.topic || "").then(msg => {
      if (selectedNode?.id === node.id || nodeCache.current.get(node.id)?.isFocused) setChatLog(msg);
    });

    if (node.isExpanded) return;
    setLoading(true);
    try {
      const response = await gemini.expandNode(node.label, mission?.topic || "", [...nodeCache.current.keys()], mission?.type || 'DEEP_DIVE');
      const cached = nodeCache.current.get(node.id);
      if (cached) cached.isExpanded = true;
      processNewData(response, node, (node.depth || 0) + 1);
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  }, [mission, selectedNode]);

  if (!initialized) {
    return (
      <div className="h-screen bg-[#020617] flex items-center justify-center">
        <div className="text-center space-y-8 animate-pulse">
          <div className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-indigo-500 tracking-tighter">OMEGA POINT</div>
          <div className="flex items-center justify-center gap-4">
            <div className="w-1.5 h-1.5 rounded-full bg-sky-500 animate-ping" />
            <div className="text-[10px] text-slate-500 font-bold tracking-[0.5em] uppercase">Materializing Adaptive Command Center</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 font-sans selection:bg-sky-500/40 overflow-hidden">

      {/* Dynamic Command Header */}
      <header className="z-20 p-6 bg-slate-950/40 backdrop-blur-3xl border-b border-white/5 flex items-center gap-10">
        <div className="flex items-center gap-5">
          <div className={`w-14 h-14 rounded-[1.5rem] flex items-center justify-center shadow-2xl transition-all duration-1000 ${autoExplode ? 'bg-sky-500 shadow-sky-500/50 scale-110' : 'bg-slate-900 border border-white/10'}`}>
            <svg className={`w-8 h-8 ${autoExplode ? 'text-white' : 'text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </div>
          <div className="hidden xl:block">
            <h1 className="text-2xl font-black tracking-tighter italic text-transparent bg-clip-text bg-gradient-to-r from-sky-400 via-indigo-400 to-emerald-400">OMEGA COMMAND</h1>
            <div className="text-[9px] font-black tracking-[0.4em] text-slate-500 uppercase">Collective Intelligence v10.0</div>
          </div>
        </div>

        <div className="flex-1 max-w-2xl flex items-center gap-3">
          <input 
            type="text" 
            value={topic} 
            onChange={e => setTopic(e.target.value)}
            placeholder="Initialize Neural Inquiry..."
            className="flex-1 bg-slate-900/50 border border-white/5 rounded-3xl px-8 py-4 focus:outline-none focus:ring-4 focus:ring-sky-500/10 transition-all text-sm font-bold placeholder:text-slate-800"
          />
          <div className="flex bg-slate-950/50 p-2 rounded-3xl border border-white/5 gap-1">
             {(['DEEP_DIVE', 'BREADTH_SCAN', 'FOUNDATIONS'] as MissionType[]).map(type => (
               <button 
                 key={type} 
                 onClick={() => startMission(type)}
                 disabled={loading}
                 className={`px-6 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all ${mission?.type === type ? 'bg-sky-500 text-white shadow-lg' : 'text-slate-600 hover:text-white hover:bg-white/5'}`}
               >
                 {type.split('_')[0]}
               </button>
             ))}
          </div>
        </div>

        <div className="flex items-center gap-6">
           {/* Synergy Meter */}
           <div className="flex flex-col items-end gap-1">
              <div className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Synergy Convergence</div>
              <div className="w-32 h-1.5 bg-slate-900 rounded-full overflow-hidden border border-white/5">
                 <div className="h-full bg-gradient-to-r from-sky-500 to-indigo-500 transition-all duration-1000" style={{ width: `${mission?.synergyLevel || 0}%` }} />
              </div>
           </div>

           <button 
             onClick={() => setAutoExplode(!autoExplode)}
             className={`px-8 py-3 rounded-3xl border transition-all flex items-center gap-4 ${autoExplode ? 'border-sky-500/40 bg-sky-500/5 text-sky-400 shadow-[0_0_20px_rgba(14,165,233,0.1)]' : 'border-white/5 bg-slate-900/30 text-slate-700'}`}
           >
             <div className={`w-2.5 h-2.5 rounded-full ${autoExplode ? 'bg-sky-500 animate-pulse' : 'bg-slate-800'}`} />
             <span className="text-[10px] font-black uppercase tracking-[0.2em]">Pilot Pilot</span>
           </button>
        </div>
      </header>

      <main className="flex-1 relative">
        {graphData.nodes.length > 0 ? (
          <>
            <Graph data={graphData} onNodeClick={handleNodeClick} isLoading={loading} synergyLevel={mission?.synergyLevel || 0} />

            {/* Real-time Mission Status */}
            <div className="absolute top-8 left-8 p-8 bg-slate-950/60 backdrop-blur-2xl border border-white/5 rounded-[3rem] w-80 space-y-6 shadow-2xl animate-in slide-in-from-left-8 duration-1000">
               <div>
                  <div className="text-[10px] font-black text-sky-500 uppercase tracking-widest mb-1">Active Mission Log</div>
                  <h2 className="text-2xl font-black text-white italic tracking-tighter truncate">{mission?.topic}</h2>
               </div>

               <div className="space-y-4">
                  <div className="space-y-2">
                     <div className="flex justify-between text-[9px] font-black text-slate-500 uppercase tracking-widest">
                        <span>Milestones</span>
                        <span>{Math.round(mission?.progress || 0)}%</span>
                     </div>
                     <div className="h-1 bg-slate-900 rounded-full"><div className="h-full bg-sky-500 rounded-full transition-all duration-1000" style={{ width: `${mission?.progress}%` }} /></div>
                  </div>

                  <ul className="space-y-3">
                     {mission?.milestones.map((m, i) => (
                        <li key={i} className={`flex items-start gap-3 text-[10px] font-bold ${mission.progress > (i+1)*30 ? 'text-sky-400' : 'text-slate-600'}`}>
                           <div className={`mt-1 w-1.5 h-1.5 rounded-full ${mission.progress > (i+1)*30 ? 'bg-sky-500' : 'bg-slate-800'}`} />
                           {m}
                        </li>
                     ))}
                  </ul>
               </div>

               {mission?.lastSynthesis && (
                 <div className="p-5 bg-sky-500/5 rounded-3xl border border-sky-500/10 animate-in fade-in duration-1000">
                    <div className="text-[9px] font-black text-sky-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                       <div className="w-1 h-1 bg-sky-400 rounded-full animate-ping" />
                       Meta Synthesis
                    </div>
                    <p className="text-[10px] text-slate-300 leading-relaxed italic">{mission.lastSynthesis}</p>
                 </div>
               )}
            </div>
          </>
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 bg-[#020617]">
             <div className="max-w-xl text-center space-y-16">
                <div className="relative group scale-110">
                   <div className="absolute inset-0 bg-sky-500/10 blur-[120px] animate-pulse" />
                   <div className="relative w-40 h-40 bg-slate-950 border border-white/5 rounded-[3.5rem] flex items-center justify-center mx-auto shadow-2xl transition-transform duration-700 group-hover:scale-105">
                      <svg className="w-20 h-20 text-sky-500/40" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                         <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 11c0 3.517-1.009 6.799-2.753 9.571m-3.44-2.04l.054-.09A10.003 10.003 0 0014 4.13V4a2 2 0 114 0v.13c0 1.547.35 3.01.976 4.315a10.002 10.002 0 01-4.226 12.023l-.07.038" />
                      </svg>
                   </div>
                </div>
                <div className="space-y-8">
                   <h2 className="text-5xl font-black tracking-tighter italic uppercase text-white">Omega Integration</h2>
                   <p className="text-slate-500 text-lg font-medium leading-relaxed max-w-md mx-auto">
                      Transitioning into <span className="text-sky-400 underline decoration-sky-500/20 underline-offset-8 italic">fully adaptive intelligence</span>. Seed a mission to begin collective resonance.
                   </p>
                   <div className="pt-8 flex justify-center gap-12 text-[10px] font-black text-slate-700 uppercase tracking-[0.5em]">
                      <span>Emergent Patterns</span>
                      <span>•</span>
                      <span>Predictive Discovery</span>
                   </div>
                </div>
             </div>
          </div>
        )}

        {/* Holistic Adaptive Insight Overlay */}
        {selectedNode && (
          <div className="absolute top-10 right-10 w-[440px] max-h-[calc(100vh-200px)] bg-slate-950/80 backdrop-blur-3xl border border-white/5 rounded-[4rem] shadow-[0_50px_120px_rgba(0,0,0,0.95)] z-50 overflow-hidden flex flex-col animate-in slide-in-from-right-12 duration-1000 border-t-white/10">
             {selectedNode.isGhost ? (
               <div className="p-16 text-center space-y-8 h-full flex flex-col justify-center">
                  <div className="relative inline-block mx-auto mb-4">
                     <div className="w-16 h-16 bg-slate-800/20 rounded-full blur-xl animate-pulse" />
                     <svg className="w-12 h-12 text-slate-700 absolute inset-0 m-auto" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" />
                     </svg>
                  </div>
                  <div className="space-y-4">
                    <div className="text-slate-700 text-[10px] font-black uppercase tracking-[0.6em]">Predictive Ghost Node</div>
                    <h3 className="text-3xl font-black text-slate-500 italic tracking-tighter">{selectedNode.label}</h3>
                  </div>
                  <p className="text-xs text-slate-600 leading-relaxed font-bold italic px-6 opacity-60">This concept is currently a ghost in the machine. Materializing this vector will increase global mission synergy.</p>
                  <button onClick={() => handleNodeClick(selectedNode)} className="bg-white/5 hover:bg-white/10 text-[9px] font-black text-slate-500 px-8 py-3 rounded-full uppercase tracking-widest transition-all">Force Resonance</button>
               </div>
             ) : (
               <>
                 <div className="relative h-64 bg-slate-900 group">
                    {selectedNode.wikiImage ? (
                      <img src={selectedNode.wikiImage} className="w-full h-full object-cover brightness-[0.4] group-hover:brightness-50 transition-all duration-1000" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-[15rem] font-black text-white/5 italic select-none absolute -bottom-16 -right-16">{selectedNode.label[0]}</div>
                    )}
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent" />
                    <button onClick={() => setSelectedNode(null)} className="absolute top-8 right-8 p-3 bg-black/60 hover:bg-black rounded-full transition-all text-white/40 hover:text-white border border-white/5">
                       <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 18L18 6M6 6l12 12" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/></svg>
                    </button>
                 </div>
                 <div className="p-12 flex-1 overflow-y-auto space-y-10 custom-scrollbar">
                    <div className="space-y-4">
                       <div className="flex items-center gap-4">
                          <span className="text-[10px] font-black bg-sky-500 text-white px-3 py-1 rounded-lg uppercase tracking-widest">Level 0{selectedNode.depth}</span>
                          <span className="text-[10px] font-black border border-white/10 text-slate-500 px-3 py-1 rounded-lg uppercase tracking-widest">Weight {selectedNode.strength?.toFixed(3)}</span>
                       </div>
                       <h3 className="text-4xl font-black tracking-tighter text-white italic">{selectedNode.label}</h3>
                    </div>

                    <div className="space-y-8">
                       <div className="relative">
                          <div className="absolute -left-8 top-0 bottom-0 w-1 bg-gradient-to-b from-sky-500 to-indigo-500 rounded-full opacity-50" />
                          <p className="text-slate-300 font-bold text-lg leading-relaxed italic">
                             {selectedNode.description}
                          </p>
                       </div>

                       <div className="p-8 bg-black/50 rounded-[2.5rem] border border-white/5 space-y-4 shadow-inner">
                          <div className="flex items-center gap-3 text-[10px] font-black text-sky-500 uppercase tracking-widest">
                             <div className="w-1.5 h-1.5 rounded-full bg-sky-500 shadow-[0_0_10px_rgba(14,165,233,0.5)]" />
                             Omega Neural Analysis
                          </div>
                          <p className="text-sm text-slate-400 leading-relaxed font-medium italic opacity-90">{chatLog || 'Synthesizing...'}</p>
                       </div>

                       {selectedNode.wikiSummary && (
                         <div className="space-y-6 pt-4">
                            <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Global Intelligence Baseline</div>
                            <p className="text-xs text-slate-500 leading-relaxed font-medium opacity-80">{selectedNode.wikiSummary}</p>
                            <a href={selectedNode.wikiUrl} target="_blank" className="inline-flex items-center gap-3 text-[10px] font-black text-sky-500 uppercase tracking-widest hover:text-sky-300 transition-all">
                               Neural Link: Source terminal
                               <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
                            </a>
                         </div>
                       )}
                    </div>
                 </div>
               </>
             )}
          </div>
        )}
      </main>

      {/* Holistic System Footer */}
      <footer className="p-8 bg-slate-950/80 border-t border-white/5 flex items-center justify-between text-[10px] font-black uppercase tracking-[0.5em] text-slate-600">
         <div className="flex items-center gap-12">
            <div className="flex items-center gap-3">
               <div className="w-1.5 h-1.5 rounded-full bg-sky-500" />
               <span className="text-sky-500">Core: Gemini 3 Pro (Omega)</span>
            </div>
            <div className="flex items-center gap-4">
               <span className="opacity-40">Vectors Materialized</span>
               <span className="text-slate-400">{graphData.nodes.length}</span>
            </div>
            <div className="flex items-center gap-4">
               <span className="opacity-40">Facilitator Status</span>
               <span className={autoExplode ? 'text-sky-400' : 'text-slate-800'}>{autoExplode ? 'ORCHESTRATING' : 'STANDBY'}</span>
            </div>
         </div>
         <div className="flex items-center gap-10">
            <span className="flex items-center gap-4">
               <div className="flex gap-1">
                  {[...Array(5)].map((_, i) => (
                    <div key={i} className={`w-1.5 h-3 rounded-full transition-all duration-500 ${ (mission?.synergyLevel || 0) > (i+1)*20 ? 'bg-indigo-500' : 'bg-slate-900'}`} />
                  ))}
               </div>
               Neural Synergy Optimal
            </span>
         </div>
      </footer>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.05); border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.1); }
      `}</style>
    </div>
  );
};

export default App;
